      ctx.fillText(`${difficulty.toUpperCase()} • LEVEL ${levelId}`, size/2, titleY - 8);

      // Header - In-Video Timer (ticking)
      let currentSeconds = 0;
      if (frame >= INTRO_FRAMES && frame < INTRO_FRAMES + FILL_FRAMES) {
          const progress = (frame - INTRO_FRAMES) / FILL_FRAMES;
          currentSeconds = totalTime * progress;
      } else if (frame >= INTRO_FRAMES + FILL_FRAMES) {
          currentSeconds = totalTime;
      }

      // Timer has same characteristics as title (bold black outfit)
      ctx.font = 'bold 40px "Outfit", sans-serif';
      // Previous Y was titleY + 39. Moving up by 2 pixels makes it titleY + 37.
      ctx.fillText(formatTime(currentSeconds), size/2, titleY + 37);

      // Watermark
      ctx.fillStyle = c.watermark;
      ctx.font = '500 30px "Outfit", sans-serif';
      ctx.fillText("OKU: SUDOKU", size/2, size - (padding / 2));

      // Board BG
      ctx.shadowColor = "rgba(0,0,0,0.1)";
      ctx.shadowBlur = 30;
      ctx.shadowOffsetY = 10;
      ctx.fillStyle = c.boardBg;
      const r = 32;
      ctx.beginPath();
      ctx.roundRect(startX, startY, boardSize, boardSize, r);
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.shadowOffsetY = 0;

      // Clip
      ctx.save();
      ctx.beginPath();
      ctx.roundRect(startX, startY, boardSize, boardSize, r);
      ctx.clip();

      // Lines
      ctx.lineCap = 'butt';
      for (let i = 1; i < 9; i++) {
