        popFreq: 200,
        durationScale: 0.8,
        volumeScale: 0.7
    }
};

class SoundController {
    private ctx: AudioContext | null = null;
    private soundEnabled: boolean = true;
    private vibrationEnabled: boolean = true;
    private activeProfile: SoundProfile = PROFILES['snd-zen'];
    private noiseBuffer: AudioBuffer | null = null;

    setEnabled(enabled: boolean) {
        this.soundEnabled = enabled;
    }

    setVibrationEnabled(enabled: boolean) {
        this.vibrationEnabled = enabled;
    }

    setProfile(profileId: string) {
        if (PROFILES[profileId]) {
            this.activeProfile = PROFILES[profileId];
        } else {
            this.activeProfile = PROFILES['snd-zen'];
        }
    }

    private getCtx() {
        if (!this.ctx) {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            this.ctx = new AudioContext();
        }
        if (this.ctx.state === 'suspended') {
            this.ctx.resume().catch(() => {});
        }
        return this.ctx;
    }

    private getNoiseBuffer() {
        const ctx = this.getCtx();
        if (!this.noiseBuffer) {
            const bufferSize = 2 * ctx.sampleRate;
            this.noiseBuffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
            const output = this.noiseBuffer.getChannelData(0);
            for (let i = 0; i < bufferSize; i++) {
                output[i] = Math.random() * 2 - 1;
            }
        }
        return this.noiseBuffer;
    }

    private async vibrate(style: 'light' | 'medium' | 'heavy' | 'success' | 'warning' | 'error') {
        if (!this.vibrationEnabled) return;
        try {
            switch (style) {
                case 'light': await Haptics.impact({ style: ImpactStyle.Light }); break;
                case 'medium': await Haptics.impact({ style: ImpactStyle.Medium }); break;
                case 'heavy': await Haptics.impact({ style: ImpactStyle.Heavy }); break;
                case 'success': await Haptics.notification({ type: NotificationType.Success }); break;
                case 'warning': await Haptics.notification({ type: NotificationType.Warning }); break;
                case 'error': await Haptics.notification({ type: NotificationType.Error }); break;
            }
        } catch (e) {
            if (typeof navigator !== 'undefined' && navigator.vibrate) {
                const map: Record<string, number | number[]> = {
                    light: 10,
                    medium: 20,
                    heavy: 40,
                    success: [50, 50, 100],
                    warning: [30, 100],
                    error: [50, 100, 50]
                };
                navigator.vibrate(map[style]);
            }
        }
    }

    private playTone(freq: number, type: SoundProfile['type'], duration: number, volume: number) {
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;
            const vol = volume * this.activeProfile.volumeScale;
            const dur = duration * this.activeProfile.durationScale;

            if (type === 'noise') {
                const source = ctx.createBufferSource();
                source.buffer = this.getNoiseBuffer();

                const filter = ctx.createBiquadFilter();
                // For ASMR "tuned" noise, we use a resonant bandpass
                filter.type = 'bandpass';
                filter.frequency.setValueAtTime(freq, t);
                filter.Q.setValueAtTime(20, t); // High Q makes it "pitched"

                const gain = ctx.createGain();
                source.connect(filter);
                filter.connect(gain);
                gain.connect(ctx.destination);

                gain.gain.setValueAtTime(0, t);
                gain.gain.linearRampToValueAtTime(vol * 2.5, t + 0.01); // Noise is naturally quieter, boost it
                gain.gain.exponentialRampToValueAtTime(0.001, t + dur);

                source.start(t);
                source.stop(t + dur + 0.05);
            } else {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.type = type as any;
                osc.frequency.setValueAtTime(freq, t);

                gain.gain.setValueAtTime(0, t);
                gain.gain.linearRampToValueAtTime(vol, t + 0.01);
                gain.gain.exponentialRampToValueAtTime(0.001, t + dur);

                osc.start(t);
                osc.stop(t + dur + 0.05);
            }
        } catch (e) {}
    }

    private playNoiseBurst(freq: number, duration: number, volume: number, filterType: BiquadFilterType = 'highpass') {
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;
            const source = ctx.createBufferSource();
            source.buffer = this.getNoiseBuffer();

            const filter = ctx.createBiquadFilter();
            filter.type = filterType;
            filter.frequency.setValueAtTime(freq, t);

            const gain = ctx.createGain();
            source.connect(filter);
            filter.connect(gain);
            gain.connect(ctx.destination);

            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(volume * this.activeProfile.volumeScale * 1.5, t + 0.005);
            gain.gain.exponentialRampToValueAtTime(0.001, t + duration);

            source.start(t);
            source.stop(t + duration + 0.05);
        } catch (e) {}
    }

    playClick() {
        this.vibrate('light'); 
        if (this.activeProfile.type === 'noise') {
            this.playNoiseBurst(this.activeProfile.uiClickFreq, 0.08, 0.4, 'highpass');
        } else {
            this.playTone(this.activeProfile.uiClickFreq, this.activeProfile.type, 0.1, 0.5); 
        }
    }

    playTap() {
        this.vibrate('light');
        if (this.activeProfile.type === 'noise') {
            this.playNoiseBurst(this.activeProfile.uiTapFreq, 0.08, 0.4, 'highpass');
        } else {
            this.playTone(this.activeProfile.uiTapFreq, this.activeProfile.type, 0.1, 0.5); 
        }
    }

    playNumber(num: number) {
        this.vibrate('medium');
        const freq = this.activeProfile.numberFreqs[num - 1] || 440;
        this.playTone(freq, this.activeProfile.type, 0.15, 0.8); 
    }

    playPop() {
        this.vibrate('medium');
        this.playTone(this.activeProfile.popFreq, this.activeProfile.type, 0.15, 0.8); 
    }

    playLevelEnter() {
        this.vibrate('heavy');
        if (!this.soundEnabled) return;
        if (this.activeProfile.type === 'noise') {
            this.playNoiseBurst(600, 0.3, 0.6, 'lowpass');
        } else {
            try {
                const ctx = this.getCtx();
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.type = this.activeProfile.type as any;
                const t = ctx.currentTime;
                osc.frequency.setValueAtTime(this.activeProfile.popFreq, t); 
                osc.frequency.exponentialRampToValueAtTime(this.activeProfile.uiClickFreq, t + 0.2);
                gain.gain.setValueAtTime(0, t);
                gain.gain.linearRampToValueAtTime(0.8 * this.activeProfile.volumeScale, t + 0.05);
                gain.gain.linearRampToValueAtTime(0.6 * this.activeProfile.volumeScale, t + 0.15);
                gain.gain.exponentialRampToValueAtTime(0.001, t + 0.3);
                osc.start(t);
                osc.stop(t + 0.3);
            } catch (e) {}
        }
    }

    playSectionComplete() {
        this.vibrate('success');
        if (!this.soundEnabled) return;
        if (this.activeProfile.type === 'noise') {
             // Three rhythmic wooden block-like taps
             const delays = [0, 80, 160];
             delays.forEach((d, i) => {
                 setTimeout(() => this.playNoiseBurst(800 + (i * 400), 0.1, 0.6, 'bandpass'), d);
             });
        } else {
            try {
                const freqs = this.activeProfile.numberFreqs;
                const notes = [freqs[0], freqs[2], freqs[4]]; 
                notes.forEach((freq, i) => {
                    setTimeout(() => this.playTone(freq, this.activeProfile.type, 0.1, 0.5), i * 50); 
                });
            } catch (e) {}
        }
    }

    playZap() {
        this.vibrate('medium');
        if (!this.soundEnabled) return;
        if (this.activeProfile.type === 'noise') {
            this.playNoiseBurst(4000, 0.06, 0.5, 'highpass');
        } else {
            try {
                const ctx = this.getCtx();
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.type = this.activeProfile.type as any;
                const t = ctx.currentTime;
                osc.frequency.setValueAtTime(1200, t);
                osc.frequency.exponentialRampToValueAtTime(600, t + 0.15);
                gain.gain.setValueAtTime(0, t);
                gain.gain.linearRampToValueAtTime(0.8 * this.activeProfile.volumeScale, t + 0.01);
                gain.gain.exponentialRampToValueAtTime(0.001, t + 0.15);
                osc.start(t);
                osc.stop(t + 0.2);
            } catch (e) {}
        }
    }

    playScan() {
        this.vibrate('heavy');
        if (!this.soundEnabled) return;
        const ctx = this.getCtx();
        const t = ctx.currentTime;
        const source = ctx.createBufferSource();
        source.buffer = this.getNoiseBuffer();

        const filter = ctx.createBiquadFilter();
        filter.type = 'bandpass';
        filter.frequency.setValueAtTime(300, t);
        filter.frequency.exponentialRampToValueAtTime(3000, t + 0.8);
        filter.Q.setValueAtTime(5, t);

        const gain = ctx.createGain();
        source.connect(filter);
        filter.connect(gain);
        gain.connect(ctx.destination);

        gain.gain.setValueAtTime(0, t);
        gain.gain.linearRampToValueAtTime(0.4 * this.activeProfile.volumeScale, t + 0.1);
        gain.gain.linearRampToValueAtTime(0, t + 0.8);

        source.start(t);
        source.stop(t + 0.8);
    }

    playReveal() {
        this.vibrate('heavy');
        if (!this.soundEnabled) return;
        const ctx = this.getCtx();
        const t = ctx.currentTime;
        // Magic shimmer burst using filtered noise
        for (let i = 0; i < 5; i++) {
            const source = ctx.createBufferSource();
            source.buffer = this.getNoiseBuffer();
            const filter = ctx.createBiquadFilter();
            filter.type = 'bandpass';
            filter.frequency.setValueAtTime(1000 + (i * 600), t);
            filter.Q.setValueAtTime(25, t);
            const gain = ctx.createGain();
            source.connect(filter);
            filter.connect(gain);
            gain.connect(ctx.destination);
            const start = t + (i * 0.05);
            gain.gain.setValueAtTime(0, start);
            gain.gain.linearRampToValueAtTime(0.3 * this.activeProfile.volumeScale, start + 0.05);
            gain.gain.exponentialRampToValueAtTime(0.001, start + 0.6);
            source.start(start);
            source.stop(start + 0.7);
        }
    }

    playWin() {
        this.vibrate('success');
        if (!this.soundEnabled) return;
        if (this.activeProfile.type === 'noise') {
            // "Shaker" win sound with rhythmic bursts
            const ctx = this.getCtx();
            const t = ctx.currentTime;
            for (let i = 0; i < 8; i++) {
                const source = ctx.createBufferSource();
                source.buffer = this.getNoiseBuffer();
                const filter = ctx.createBiquadFilter();
                filter.type = 'highpass';
                filter.frequency.setValueAtTime(3500 + (i * 400), t);
                const gain = ctx.createGain();
                source.connect(filter);
                filter.connect(gain);
                gain.connect(ctx.destination);
                const start = t + (i * 0.1);
                gain.gain.setValueAtTime(0, start);
                gain.gain.linearRampToValueAtTime(0.25, start + 0.01);
                gain.gain.exponentialRampToValueAtTime(0.001, start + 0.12);
                source.start(start);
                source.stop(start + 0.2);
            }
        } else {
            const freqs = this.activeProfile.numberFreqs;
            const notes = [freqs[0], freqs[2], freqs[4], freqs[5]]; 
            notes.forEach((freq, i) => {
                setTimeout(() => {
                    this.playTone(freq, this.activeProfile.type, 0.6, 0.7);
                }, i * 100);
            });
        }
    }
}

