            if (p.difficulty === selectedDiff && p.status === 'completed') {
                result.completed++;
                result.totalTime += p.timeElapsed;
                if (p.bestTime && p.bestTime < result.bestTime) {
                    result.bestTime = p.bestTime;
                }
            }
        });

        return result;
