            osc.frequency.exponentialRampToValueAtTime(this.activeProfile.uiClickFreq * 1.5, t + 0.3);
            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(0.4 * this.activeProfile.volumeScale, t + 0.05);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.3);
            osc.start(t);
            osc.stop(t + 0.35);
        } catch (e) {}
    }

    playWin() {
        this.vibrate('success');
        if (!this.soundEnabled) return;
        const freqs = [523.25, 659.25, 783.99, 1046.50];
        freqs.forEach((f, i) => {
            setTimeout(() => this.playTone(f, this.activeProfile.type, 0.8, 0.15), i * 150);
        });
    }

    playZap() {
        // "Auto" Skill - Refined "Digital Precision" sequence
        // Focusing on rapid data-pips without the trailing harmonic resonance.
        this.vibrate('medium');
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;

            // Rapid sequence of precision digital pips
            const pipCount = 6; 
            for (let i = 0; i < pipCount; i++) {
                const pipTime = t + (i * 0.045);
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);

                osc.type = this.activeProfile.type === 'square' ? 'square' : 'sine';
                // Clean upward frequency sweep across the pips
                const freq = 1300 + (i * 180);
                osc.frequency.setValueAtTime(freq, pipTime);

                gain.gain.setValueAtTime(0, pipTime);
                gain.gain.linearRampToValueAtTime(0.25 * this.activeProfile.volumeScale, pipTime + 0.01);
                gain.gain.exponentialRampToValueAtTime(0.001, pipTime + 0.04);

                osc.start(pipTime);
                osc.stop(pipTime + 0.06);
            }
        } catch(e) {}
    }

    playScan() {
        // "Scan" Skill - Rhythmic digital data-scanner sound
        this.vibrate('light');
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;
            const totalDuration = 1.2;
            const pips = 12; // 12 discrete scans across the grid
            const interval = totalDuration / pips;

            for (let i = 0; i < pips; i++) {
                const pipTime = t + (i * interval);
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);

                // Digital "blip" sound
                osc.type = this.activeProfile.type as any;

                // Frequency sweep for the scanner (moving from low to high readout)
                const baseFreq = 200 + (i * 80);
                osc.frequency.setValueAtTime(baseFreq, pipTime);
                osc.frequency.exponentialRampToValueAtTime(baseFreq * 1.5, pipTime + 0.05);

                gain.gain.setValueAtTime(0, pipTime);
                gain.gain.linearRampToValueAtTime(0.15 * this.activeProfile.volumeScale, pipTime + 0.01);
                gain.gain.exponentialRampToValueAtTime(0.001, pipTime + 0.08);

                osc.start(pipTime);
                osc.stop(pipTime + 0.1);
            }

            // Subtle background hum for the scanner movement
            const hum = ctx.createOscillator();
            const humGain = ctx.createGain();
            hum.connect(humGain);
            humGain.connect(ctx.destination);
            hum.type = 'sine';
            hum.frequency.setValueAtTime(100, t);
            hum.frequency.linearRampToValueAtTime(300, t + totalDuration);
            humGain.gain.setValueAtTime(0, t);
            humGain.gain.linearRampToValueAtTime(0.05 * this.activeProfile.volumeScale, t + 0.1);
            humGain.gain.linearRampToValueAtTime(0, t + totalDuration);
            hum.start(t);
            hum.stop(t + totalDuration);

        } catch(e) {}
    }

    playReveal() {
        // "Reveal" Skill - Premium satisfying arpeggio with shimmer
        this.vibrate('medium');
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;

            // Major 7th arpeggio for premium feel
            const notes = [523.25, 659.25, 783.99, 987.77, 1046.50, 1318.51]; 

            notes.forEach((freq, i) => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);

                // Zen uses pure sine, Retro uses square for that bit-shine
                osc.type = this.activeProfile.type as any;
                const noteTime = t + (i * 0.06);
                const isLast = i === notes.length - 1;

                osc.frequency.setValueAtTime(freq, noteTime);

                gain.gain.setValueAtTime(0, noteTime);
                gain.gain.linearRampToValueAtTime(0.2 * this.activeProfile.volumeScale, noteTime + 0.02);

                // Final note rings out longer
                const release = isLast ? 1.0 : 0.4;
                gain.gain.exponentialRampToValueAtTime(0.001, noteTime + release);

                osc.start(noteTime);
                osc.stop(noteTime + release + 0.1);
            });

            // Add a subtle low-end 'thud' to ground the reveal
            const thud = ctx.createOscillator();
            const thudGain = ctx.createGain();
            thud.connect(thudGain);
            thudGain.connect(ctx.destination);
            thud.type = 'sine';
            thud.frequency.setValueAtTime(110, t);
            thudGain.gain.setValueAtTime(0, t);
            thudGain.gain.linearRampToValueAtTime(0.2 * this.activeProfile.volumeScale, t + 0.01);
            thudGain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
            thud.start(t);
            thud.stop(t + 0.6);

        } catch(e) {}
    }
}

