                // Clean upward frequency sweep across the pips
                const freq = 1300 + (i * 180);
                osc.frequency.setValueAtTime(freq, pipTime);

                gain.gain.setValueAtTime(0, pipTime);
                gain.gain.linearRampToValueAtTime(0.25 * this.activeProfile.volumeScale, pipTime + 0.01);
                gain.gain.exponentialRampToValueAtTime(0.001, pipTime + 0.04);

                osc.start(pipTime);
                osc.stop(pipTime + 0.06);
            }
        } catch(e) {}
    }

    playScan() {
        // "Scan" Skill - Mechanical "BZZZZ" scanner effect
        this.vibrate('light');
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;
            const totalDuration = 1.2;

            // Main buzzy oscillator
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            const filter = ctx.createBiquadFilter();

            // Texture LFO - creates the "BZZZZ" rattle
            const rattleLfo = ctx.createOscillator();
            const rattleGain = ctx.createGain();

            osc.connect(filter);
            filter.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'sawtooth';
            // Start at a lower growly frequency and sweep up slightly
            osc.frequency.setValueAtTime(120, t);
            osc.frequency.linearRampToValueAtTime(220, t + totalDuration);

            // Resonant filter sweep for "movement" feel
            filter.type = 'bandpass';
            filter.frequency.setValueAtTime(400, t);
            filter.frequency.exponentialRampToValueAtTime(3000, t + (totalDuration / 2));
            filter.frequency.exponentialRampToValueAtTime(800, t + totalDuration);
            filter.Q.setValueAtTime(8, t);

            // Fast amplitude modulation for the buzzing texture
            rattleLfo.type = 'square';
            rattleLfo.frequency.setValueAtTime(55, t); // 55Hz vibration
            rattleGain.gain.setValueAtTime(0.4, t);
            rattleLfo.connect(rattleGain.gain);
            // We use a helper gain to apply the rattle to the main signal
            const vGain = ctx.createGain();
            vGain.gain.setValueAtTime(1, t);
            rattleLfo.connect(vGain.gain); // Modulate the signal

            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(0.25 * this.activeProfile.volumeScale, t + 0.1);
            gain.gain.linearRampToValueAtTime(0.20 * this.activeProfile.volumeScale, t + totalDuration - 0.1);
            gain.gain.exponentialRampToValueAtTime(0.001, t + totalDuration);

            osc.start(t);
            rattleLfo.start(t);
            osc.stop(t + totalDuration);
            rattleLfo.stop(t + totalDuration);

        } catch(e) {}
    }

    playReveal() {
        // "Reveal" Skill - Premium satisfying arpeggio with shimmer
        this.vibrate('medium');
