        uiClickFreq: 110,
        uiTapFreq: 90,
        numberFreqs: [130, 140, 150, 160, 170, 180, 190, 200, 210],
        popFreq: 80,
        durationScale: 1.2,
        volumeScale: 1.2
    },
    'snd-retro': {
        id: 'snd-retro',
        type: 'square',
        uiClickFreq: 1200,
        uiTapFreq: 1000,
        numberFreqs: [440, 493.88, 554.37, 587.33, 659.25, 739.99, 830.61, 880, 987.77],
        popFreq: 300,
        durationScale: 0.7,
        volumeScale: 0.25
    }
};

class SoundController {
    private ctx: AudioContext | null = null;
    private soundEnabled: boolean = true;
    private vibrationEnabled: boolean = true;
    private activeProfile: SoundProfile = PROFILES['snd-zen'];

    setEnabled(enabled: boolean) {
        this.soundEnabled = enabled;
    }

    setVibrationEnabled(enabled: boolean) {
        this.vibrationEnabled = enabled;
    }

    setProfile(profileId: string) {
        if (PROFILES[profileId]) {
            this.activeProfile = PROFILES[profileId];
        } else {
            this.activeProfile = PROFILES['snd-zen'];
        }
    }

    private getCtx() {
        if (!this.ctx) {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            this.ctx = new AudioContext();
        }
        if (this.ctx.state === 'suspended') {
            this.ctx.resume().catch(() => {});
        }
        return this.ctx;
    }

    private async vibrate(style: 'light' | 'medium' | 'heavy' | 'success' | 'warning' | 'error') {
        if (!this.vibrationEnabled) return;
        try {
            switch (style) {
                case 'light': await Haptics.impact({ style: ImpactStyle.Light }); break;
                case 'medium': await Haptics.impact({ style: ImpactStyle.Medium }); break;
                case 'heavy': await Haptics.impact({ style: ImpactStyle.Heavy }); break;
                case 'success': await Haptics.notification({ type: NotificationType.Success }); break;
                case 'warning': await Haptics.notification({ type: NotificationType.Warning }); break;
                case 'error': await Haptics.notification({ type: NotificationType.Error }); break;
            }
        } catch (e) {
            if (typeof navigator !== 'undefined' && navigator.vibrate) {
                const map: Record<string, number | number[]> = {
                    light: 10,
                    medium: 20,
                    heavy: 40,
                    success: [50, 50, 100],
                    warning: [30, 100],
                    error: [50, 100, 50]
                };
                navigator.vibrate(map[style]);
            }
        }
    }

    private playTone(freq: number, type: SoundProfile['type'], duration: number, volume: number, pitchDrop: boolean = false) {
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;
            const vol = volume * this.activeProfile.volumeScale;
            const dur = duration * this.activeProfile.durationScale;

            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.type = type as any;

            if (pitchDrop) {
                osc.frequency.setValueAtTime(freq, t);
                osc.frequency.exponentialRampToValueAtTime(freq * 0.5, t + dur);
            } else {
                osc.frequency.setValueAtTime(freq, t);
            }

            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(vol, t + 0.01);
            gain.gain.exponentialRampToValueAtTime(0.001, t + dur);

            osc.start(t);
            osc.stop(t + dur + 0.05);
        } catch (e) {}
    }

    playClick() {
        this.vibrate('light'); 
        const isThud = this.activeProfile.id === 'snd-thud';
        this.playTone(this.activeProfile.uiClickFreq, this.activeProfile.type, 0.1, 0.5, isThud); 
    }

    playTap() {
        this.vibrate('light');
        const isThud = this.activeProfile.id === 'snd-thud';
        this.playTone(this.activeProfile.uiTapFreq, this.activeProfile.type, 0.1, 0.5, isThud); 
    }

    playNumber(num: number) {
        this.vibrate('medium');
        const freq = this.activeProfile.numberFreqs[num - 1] || 440;
        const isThud = this.activeProfile.id === 'snd-thud';
        this.playTone(freq, this.activeProfile.type, 0.15, 0.8, isThud); 
    }

    playPop() {
        this.vibrate('medium');
        const isThud = this.activeProfile.id === 'snd-thud';
        this.playTone(this.activeProfile.popFreq, this.activeProfile.type, 0.15, 0.8, isThud); 
    }

    playLevelEnter() {
        this.vibrate('heavy');
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.type = this.activeProfile.type as any;
            const t = ctx.currentTime;
            const isThud = this.activeProfile.id === 'snd-thud';

            if (isThud) {
                osc.frequency.setValueAtTime(150, t);
                osc.frequency.exponentialRampToValueAtTime(60, t + 0.5);
                gain.gain.setValueAtTime(0, t);
                gain.gain.linearRampToValueAtTime(0.5 * this.activeProfile.volumeScale, t + 0.05);
                gain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
                osc.start(t);
                osc.stop(t + 0.55);
            } else {
                osc.frequency.setValueAtTime(this.activeProfile.uiClickFreq, t);
                osc.frequency.exponentialRampToValueAtTime(this.activeProfile.uiClickFreq * 1.5, t + 0.3);
                gain.gain.setValueAtTime(0, t);
                gain.gain.linearRampToValueAtTime(0.4 * this.activeProfile.volumeScale, t + 0.05);
                gain.gain.exponentialRampToValueAtTime(0.001, t + 0.3);
                osc.start(t);
                osc.stop(t + 0.35);
            }
        } catch (e) {}
    }

    playWin() {
        this.vibrate('success');
        if (!this.soundEnabled) return;
        const isThud = this.activeProfile.id === 'snd-thud';

        if (isThud) {
            // A series of melodic thuds for win
            const thudNotes = [110, 138.59, 164.81, 220]; // A2 Major chord
            thudNotes.forEach((f, i) => {
                setTimeout(() => this.playTone(f, this.activeProfile.type, 0.6, 0.3, true), i * 200);
            });
        } else {
            const freqs = [523.25, 659.25, 783.99, 1046.50];
            freqs.forEach((f, i) => {
                setTimeout(() => this.playTone(f, this.activeProfile.type, 0.8, 0.15), i * 150);
            });
        }
    }

    playZap() {
        // "Auto" Skill - Refined "Digital Precision" sequence
        // Focusing on rapid data-pips without the trailing harmonic resonance.
        this.vibrate('medium');
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;

            // Rapid sequence of precision digital pips
            const pipCount = 6; 
            for (let i = 0; i < pipCount; i++) {
                const pipTime = t + (i * 0.045);
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);

                osc.type = this.activeProfile.type === 'square' ? 'square' : 'sine';
                // Clean upward frequency sweep across the pips
                const freq = 1300 + (i * 180);
                osc.frequency.setValueAtTime(freq, pipTime);

                gain.gain.setValueAtTime(0, pipTime);
                gain.gain.linearRampToValueAtTime(0.25 * this.activeProfile.volumeScale, pipTime + 0.01);
                gain.gain.exponentialRampToValueAtTime(0.001, pipTime + 0.04);

                osc.start(pipTime);
                osc.stop(pipTime + 0.06);
            }
        } catch(e) {}
    }

    playScan() {
        // "Scan" Skill - Mechanical "BZZZZ" scanner effect
        this.vibrate('light');
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;
            const totalDuration = 1.2;

            // Main buzzy oscillator
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            const filter = ctx.createBiquadFilter();

            // Texture LFO - creates the "BZZZZ" rattle
            const rattleLfo = ctx.createOscillator();
            const rattleGain = ctx.createGain();

            osc.connect(filter);
            filter.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'sawtooth';
            // Start at a lower growly frequency and sweep up slightly
            osc.frequency.setValueAtTime(120, t);
            osc.frequency.linearRampToValueAtTime(220, t + totalDuration);

            // Resonant filter sweep for "movement" feel
            filter.type = 'bandpass';
            filter.frequency.setValueAtTime(400, t);
            filter.frequency.exponentialRampToValueAtTime(3000, t + (totalDuration / 2));
            filter.frequency.exponentialRampToValueAtTime(800, t + totalDuration);
            filter.Q.setValueAtTime(8, t);

            // Fast amplitude modulation for the buzzing texture
            rattleLfo.type = 'square';
            rattleLfo.frequency.setValueAtTime(55, t); // 55Hz vibration
            rattleGain.gain.setValueAtTime(0.4, t);
            rattleLfo.connect(rattleGain.gain);
            // We use a helper gain to apply the rattle to the main signal
            const vGain = ctx.createGain();
            vGain.gain.setValueAtTime(1, t);
            rattleLfo.connect(vGain.gain); // Modulate the signal

            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(0.25 * this.activeProfile.volumeScale, t + 0.1);
            gain.gain.linearRampToValueAtTime(0.20 * this.activeProfile.volumeScale, t + totalDuration - 0.1);
            gain.gain.exponentialRampToValueAtTime(0.001, t + totalDuration);

            osc.start(t);
            rattleLfo.start(t);
            osc.stop(t + totalDuration);
            rattleLfo.stop(t + totalDuration);

        } catch(e) {}
    }

    playReveal() {
        // "Reveal" Skill - Premium satisfying arpeggio with shimmer
        this.vibrate('medium');
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;

            // Major 7th arpeggio for premium feel
            const notes = [523.25, 659.25, 783.99, 987.77, 1046.50, 1318.51]; 

            notes.forEach((freq, i) => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);

                // Zen uses pure sine, Retro uses square for that bit-shine
                osc.type = this.activeProfile.type as any;
                const noteTime = t + (i * 0.06);
                const isLast = i === notes.length - 1;

                osc.frequency.setValueAtTime(freq, noteTime);

                gain.gain.setValueAtTime(0, noteTime);
                gain.gain.linearRampToValueAtTime(0.2 * this.activeProfile.volumeScale, noteTime + 0.02);

                // Final note rings out longer
                const release = isLast ? 1.0 : 0.4;
                gain.gain.exponentialRampToValueAtTime(0.001, noteTime + release);

                osc.start(noteTime);
                osc.stop(noteTime + release + 0.1);
            });

            // Add a subtle low-end 'thud' to ground the reveal
            const thud = ctx.createOscillator();
            const thudGain = ctx.createGain();
            thud.connect(thudGain);
            thudGain.connect(ctx.destination);
            thud.type = 'sine';
            thud.frequency.setValueAtTime(110, t);
            thudGain.gain.setValueAtTime(0, t);
            thudGain.gain.linearRampToValueAtTime(0.2 * this.activeProfile.volumeScale, t + 0.01);
            thudGain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
            thud.start(t);
            thud.stop(t + 0.6);

        } catch(e) {}
    }
}

