export function formatTimeShort(totalSeconds: number) {
    const total = Math.floor(totalSeconds);
    const mins = Math.floor(total / 60);
    const secs = total % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
}

import { Haptics, ImpactStyle, NotificationType } from '@capacitor/haptics';

interface SoundProfile {
    id: string;
    type: 'sine' | 'square' | 'triangle' | 'sawtooth';
    uiClickFreq: number;
    uiTapFreq: number;
    numberFreqs: number[];
    popFreq: number;
    durationScale: number;
    volumeScale: number;
}

const PROFILES: Record<string, SoundProfile> = {
    'snd-zen': {
        id: 'snd-zen',
        type: 'sine',
        uiClickFreq: 800,
        uiTapFreq: 600,
        numberFreqs: [523.25, 587.33, 659.25, 783.99, 880.00, 1046.50, 1174.66, 1318.51, 1567.98],
        popFreq: 400,
        durationScale: 1.0,
        volumeScale: 1.0
    },
    'snd-thud': {
        id: 'snd-thud',
        type: 'sine',
        uiClickFreq: 110,
        uiTapFreq: 90,
        numberFreqs: [130, 140, 150, 160, 170, 180, 190, 200, 210],
        popFreq: 80,
        durationScale: 1.2,
        volumeScale: 1.2
    },
    'snd-retro': {
        id: 'snd-retro',
        type: 'square',
        uiClickFreq: 1200,
        uiTapFreq: 1000,
        numberFreqs: [440, 493.88, 554.37, 587.33, 659.25, 739.99, 830.61, 880, 987.77],
        popFreq: 300,
        durationScale: 0.7,
        volumeScale: 0.25
    }
};

class SoundController {
    private ctx: AudioContext | null = null;
    private soundEnabled: boolean = true;
    private vibrationEnabled: boolean = true;
    private activeProfile: SoundProfile = PROFILES['snd-zen'];

    setEnabled(enabled: boolean) {
        this.soundEnabled = enabled;
    }

    setVibrationEnabled(enabled: boolean) {
        this.vibrationEnabled = enabled;
    }

    setProfile(profileId: string) {
        if (PROFILES[profileId]) {
            this.activeProfile = PROFILES[profileId];
        } else {
            this.activeProfile = PROFILES['snd-zen'];
        }
    }

    private getCtx() {
        if (!this.ctx) {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            this.ctx = new AudioContext();
        }
        if (this.ctx.state === 'suspended') {
            this.ctx.resume().catch(() => {});
        }
        return this.ctx;
    }

    private async vibrate(style: 'light' | 'medium' | 'heavy' | 'success' | 'warning' | 'error') {
        if (!this.vibrationEnabled) return;
        try {
            switch (style) {
                case 'light': await Haptics.impact({ style: ImpactStyle.Light }); break;
                case 'medium': await Haptics.impact({ style: ImpactStyle.Medium }); break;
                case 'heavy': await Haptics.impact({ style: ImpactStyle.Heavy }); break;
                case 'success': await Haptics.notification({ type: NotificationType.Success }); break;
                case 'warning': await Haptics.notification({ type: NotificationType.Warning }); break;
                case 'error': await Haptics.notification({ type: NotificationType.Error }); break;
            }
        } catch (e) {
            if (typeof navigator !== 'undefined' && navigator.vibrate) {
                const map: Record<string, number | number[]> = {
                    light: 10,
                    medium: 20,
                    heavy: 40,
                    success: [50, 50, 100],
                    warning: [30, 100],
                    error: [50, 100, 50]
                };
                navigator.vibrate(map[style]);
            }
        }
    }

    private playTone(freq: number, type: SoundProfile['type'], duration: number, volume: number, pitchDrop: boolean = false) {
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;
            const vol = volume * this.activeProfile.volumeScale;
            const dur = duration * this.activeProfile.durationScale;

            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.type = type as any;

            if (pitchDrop) {
                osc.frequency.setValueAtTime(freq, t);
                osc.frequency.exponentialRampToValueAtTime(freq * 0.5, t + dur);
            } else {
                osc.frequency.setValueAtTime(freq, t);
            }

            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(vol, t + 0.01);
            gain.gain.exponentialRampToValueAtTime(0.001, t + dur);

            osc.start(t);
            osc.stop(t + dur + 0.05);
        } catch (e) {}
    }

    playClick() {
        this.vibrate('light'); 
        const isThud = this.activeProfile.id === 'snd-thud';
        this.playTone(this.activeProfile.uiClickFreq, this.activeProfile.type, 0.1, 0.5, isThud); 
    }

    playTap() {
        this.vibrate('light');
        const isThud = this.activeProfile.id === 'snd-thud';
        this.playTone(this.activeProfile.uiTapFreq, this.activeProfile.type, 0.1, 0.5, isThud); 
    }

    playNumber(num: number) {
        this.vibrate('medium');
        const freq = this.activeProfile.numberFreqs[num - 1] || 440;
        const isThud = this.activeProfile.id === 'snd-thud';
        this.playTone(freq, this.activeProfile.type, 0.15, 0.8, isThud); 
    }

    playPop() {
        this.vibrate('medium');
        const isThud = this.activeProfile.id === 'snd-thud';
        this.playTone(this.activeProfile.popFreq, this.activeProfile.type, 0.15, 0.8, isThud); 
    }

    playLevelEnter() {
        this.vibrate('heavy');
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.type = this.activeProfile.type as any;
            const t = ctx.currentTime;
            const isThud = this.activeProfile.id === 'snd-thud';

            if (isThud) {
                osc.frequency.setValueAtTime(150, t);
                osc.frequency.exponentialRampToValueAtTime(60, t + 0.5);
                gain.gain.setValueAtTime(0, t);
                gain.gain.linearRampToValueAtTime(0.5 * this.activeProfile.volumeScale, t + 0.05);
                gain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
                osc.start(t);
                osc.stop(t + 0.55);
            } else {
                osc.frequency.setValueAtTime(this.activeProfile.uiClickFreq, t);
                osc.frequency.exponentialRampToValueAtTime(this.activeProfile.uiClickFreq * 1.5, t + 0.3);
                gain.gain.setValueAtTime(0, t);
                gain.gain.linearRampToValueAtTime(0.4 * this.activeProfile.volumeScale, t + 0.05);
                gain.gain.exponentialRampToValueAtTime(0.001, t + 0.3);
                osc.start(t);
                osc.stop(t + 0.35);
            }
        } catch (e) {}
    }

    playWin() {
        this.vibrate('success');
        if (!this.soundEnabled) return;
        const isThud = this.activeProfile.id === 'snd-thud';

        if (isThud) {
            // A series of melodic thuds for win
            const thudNotes = [110, 138.59, 164.81, 220]; // A2 Major chord
            thudNotes.forEach((f, i) => {
                setTimeout(() => this.playTone(f, this.activeProfile.type, 0.6, 0.3, true), i * 200);
            });
        } else {
            const freqs = [523.25, 659.25, 783.99, 1046.50];
            freqs.forEach((f, i) => {
                setTimeout(() => this.playTone(f, this.activeProfile.type, 0.8, 0.15), i * 150);
            });
        }
    }

    playPreview(profileId: string) {
        if (!this.soundEnabled) return;
        const profile = PROFILES[profileId];
        if (!profile) return;

        this.vibrate('medium');
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;
            const vol = 0.3 * profile.volumeScale;

            if (profileId === 'snd-zen') {
                const notes = [523.25, 659.25, 783.99]; // C Major
                notes.forEach((f, i) => {
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.connect(gain);
                    gain.connect(ctx.destination);
                    osc.type = 'sine';
                    osc.frequency.setValueAtTime(f, t + (i * 0.15));
                    gain.gain.setValueAtTime(0, t + (i * 0.15));
                    gain.gain.linearRampToValueAtTime(vol, t + (i * 0.15) + 0.05);
                    gain.gain.exponentialRampToValueAtTime(0.001, t + (i * 0.15) + 0.6);
                    osc.start(t + (i * 0.15));
                    osc.stop(t + (i * 0.15) + 0.7);
                });
            } else if (profileId === 'snd-retro') {
                const notes = [440, 880, 1320];
                notes.forEach((f, i) => {
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.connect(gain);
                    gain.connect(ctx.destination);
                    osc.type = 'square';
                    osc.frequency.setValueAtTime(f, t + (i * 0.08));
                    gain.gain.setValueAtTime(0, t + (i * 0.08));
                    gain.gain.linearRampToValueAtTime(vol * 0.4, t + (i * 0.08) + 0.01);
                    gain.gain.exponentialRampToValueAtTime(0.001, t + (i * 0.08) + 0.15);
                    osc.start(t + (i * 0.08));
                    osc.stop(t + (i * 0.08) + 0.2);
                });
            } else if (profileId === 'snd-thud') {
                const notes = [110, 80];
                notes.forEach((f, i) => {
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.connect(gain);
                    gain.connect(ctx.destination);
                    osc.type = 'sine';
                    osc.frequency.setValueAtTime(f, t + (i * 0.2));
                    osc.frequency.exponentialRampToValueAtTime(f * 0.6, t + (i * 0.2) + 0.3);
                    gain.gain.setValueAtTime(0, t + (i * 0.2));
                    gain.gain.linearRampToValueAtTime(vol * 1.5, t + (i * 0.2) + 0.02);
                    gain.gain.exponentialRampToValueAtTime(0.001, t + (i * 0.2) + 0.4);
                    osc.start(t + (i * 0.2));
                    osc.stop(t + (i * 0.2) + 0.5);
                });
            }
        } catch (e) {}
    }

    playZap() {
        // "Auto" Skill - Refined "Digital Precision" sequence
        // Focusing on rapid data-pips without the trailing harmonic resonance.
        this.vibrate('medium');
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;

            // Rapid sequence of precision digital pips
            const pipCount = 6; 
            for (let i = 0; i < pipCount; i++) {
                const pipTime = t + (i * 0.045);
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);

                osc.type = this.activeProfile.type === 'square' ? 'square' : 'sine';
                // Clean upward frequency sweep across the pips
                const freq = 1300 + (i * 180);
                osc.frequency.setValueAtTime(freq, pipTime);

                gain.gain.setValueAtTime(0, pipTime);
                gain.gain.linearRampToValueAtTime(0.25 * this.activeProfile.volumeScale, pipTime + 0.01);
                gain.gain.exponentialRampToValueAtTime(0.001, pipTime + 0.04);

                osc.start(pipTime);
                osc.stop(pipTime + 0.06);
            }
        } catch(e) {}
    }

    playScan() {
        // "Scan" Skill - Mechanical "BZZZZ" scanner effect
        this.vibrate('light');
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;
            const totalDuration = 1.2;

            // Main buzzy oscillator
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            const filter = ctx.createBiquadFilter();

            // Texture LFO - creates the "BZZZZ" rattle
            const rattleLfo = ctx.createOscillator();
            const rattleGain = ctx.createGain();

            osc.connect(filter);
            filter.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'sawtooth';
            // Start at a lower growly frequency and sweep up slightly
            osc.frequency.setValueAtTime(120, t);
            osc.frequency.linearRampToValueAtTime(220, t + totalDuration);

            // Resonant filter sweep for "movement" feel
            filter.type = 'bandpass';
            filter.frequency.setValueAtTime(400, t);
            filter.frequency.exponentialRampToValueAtTime(3000, t + (totalDuration / 2));
            filter.frequency.exponentialRampToValueAtTime(800, t + totalDuration);
            filter.Q.setValueAtTime(8, t);

            // Fast amplitude modulation for the buzzing texture
            rattleLfo.type = 'square';
            rattleLfo.frequency.setValueAtTime(55, t); // 55Hz vibration
            rattleGain.gain.setValueAtTime(0.4, t);
            rattleLfo.connect(rattleGain.gain);
            // We use a helper gain to apply the rattle to the main signal
            const vGain = ctx.createGain();
            vGain.gain.setValueAtTime(1, t);
            rattleLfo.connect(vGain.gain); // Modulate the signal

            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(0.25 * this.activeProfile.volumeScale, t + 0.1);
            gain.gain.linearRampToValueAtTime(0.20 * this.activeProfile.volumeScale, t + totalDuration - 0.1);
            gain.gain.exponentialRampToValueAtTime(0.001, t + totalDuration);

            osc.start(t);
            rattleLfo.start(t);
            osc.stop(t + totalDuration);
            rattleLfo.stop(t + totalDuration);

        } catch(e) {}
    }

    playReveal() {
        // "Reveal" Skill - Premium satisfying arpeggio with shimmer
        this.vibrate('medium');
        if (!this.soundEnabled) return;
        try {
            const ctx = this.getCtx();
            const t = ctx.currentTime;

            // Major 7th arpeggio for premium feel
            const notes = [523.25, 659.25, 783.99, 987.77, 1046.50, 1318.51]; 

            notes.forEach((freq, i) => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);

                // Zen uses pure sine, Retro uses square for that bit-shine
                osc.type = this.activeProfile.type as any;
                const noteTime = t + (i * 0.06);
                const isLast = i === notes.length - 1;

                osc.frequency.setValueAtTime(freq, noteTime);

                gain.gain.setValueAtTime(0, noteTime);
                gain.gain.linearRampToValueAtTime(0.2 * this.activeProfile.volumeScale, noteTime + 0.02);

                // Final note rings out longer
                const release = isLast ? 1.0 : 0.4;
                gain.gain.exponentialRampToValueAtTime(0.001, noteTime + release);

                osc.start(noteTime);
                osc.stop(noteTime + release + 0.1);
            });

            // Add a subtle low-end 'thud' to ground the reveal
            const thud = ctx.createOscillator();
            const thudGain = ctx.createGain();
            thud.connect(thudGain);
            thudGain.connect(ctx.destination);
            thud.type = 'sine';
            thud.frequency.setValueAtTime(110, t);
            thudGain.gain.setValueAtTime(0, t);
            thudGain.gain.linearRampToValueAtTime(0.2 * this.activeProfile.volumeScale, t + 0.01);
            thudGain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
            thud.start(t);
            thud.stop(t + 0.6);

        } catch(e) {}
    }
}

export const sounds = new SoundController();

import React, { useState, useRef, useEffect } from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { STATIC_BACKGROUNDS, DYNAMIC_BACKGROUNDS, NUMBER_COLORS, SKILLS, SOUND_PACKS } from '../../utils/constants';
import { SkillTooltip } from '../ui/SkillTooltip';

interface StoreScreenProps {
    points: number;
    onBack: () => void;
    purchasedSkills: string[];
    enabledSkills: string[];
    purchasedBackgrounds: string[];
    purchasedNumberColors: string[];
    purchasedSoundPacks: string[];
    selectedBackgroundId: string | null;
    selectedNumberColorId: string;
    selectedSoundPackId: string;
    onPurchase: (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => void;
    onSelectBackground: (id: string) => void;
    onSelectNumberColor: (id: string) => void;
    onSelectSoundPack: (id: string) => void;
    onToggleSkill: (id: string) => void;
}

export const StoreScreen: React.FC<StoreScreenProps> = ({
    points,
    onBack,
    purchasedSkills,
    enabledSkills,
    purchasedBackgrounds,
    purchasedNumberColors,
    purchasedSoundPacks,
    selectedBackgroundId,
    selectedNumberColorId,
    selectedSoundPackId,
    onPurchase,
    onSelectBackground,
    onSelectNumberColor,
    onSelectSoundPack,
    onToggleSkill
}) => {
    const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
    const [isClosing, setIsClosing] = useState(false);
    const closeTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const storeContainerRef = useRef<HTMLDivElement>(null);

    const closeTooltip = () => {
        if (!activeTooltipId || isClosing) return;
        setIsClosing(true);
        if (closeTimeoutRef.current) clearTimeout(closeTimeoutRef.current);
        closeTimeoutRef.current = setTimeout(() => {
            setActiveTooltipId(null);
            setIsClosing(false);
        }, 150);
    };

    // Global listener to handle "tapping anywhere else"
    useEffect(() => {
        const handleGlobalClick = (e: MouseEvent) => {
            if (!activeTooltipId) return;

            const target = e.target as HTMLElement;
            const isButton = target.closest('button');
            const isItemButton = isButton && (isButton.hasAttribute('data-tooltip-trigger'));

            if (!isItemButton) {
                closeTooltip();
            }
        };

        document.addEventListener('mousedown', handleGlobalClick);
        return () => document.removeEventListener('mousedown', handleGlobalClick);
    }, [activeTooltipId, isClosing]);

    const handleItemTooltip = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        sounds.playClick();

        if (activeTooltipId === id) {
            closeTooltip();
        } else {
            setActiveTooltipId(id);
            setIsClosing(false);
        }
    };

    const handleSoundPackClick = (e: React.MouseEvent, pack: typeof SOUND_PACKS[0]) => {
        const isPurchased = purchasedSoundPacks.includes(pack.id);
        const isSelected = selectedSoundPackId === pack.id;

        // Preview the sound whenever clicked
        sounds.playPreview(pack.id);

        if (!isPurchased) {
            onPurchase(pack, 'sound');
        } else {
            if (!isSelected) {
                onSelectSoundPack(pack.id);
                if (activeTooltipId === pack.id) closeTooltip();
            } else {
                handleItemTooltip(e, pack.id);
            }
        }
    };

    const handleSkillClick = (e: React.MouseEvent, skill: typeof SKILLS[0]) => {
        const isPurchased = purchasedSkills.includes(skill.id);

        if (!isPurchased) {
            onPurchase(skill, 'skill');
        } else {
            handleItemTooltip(e, skill.id);
        }
    };

    const handleToggleClick = (e: React.MouseEvent, skillId: string) => {
        e.stopPropagation();
        sounds.playClick();
        onToggleSkill(skillId);
    };

    return (
        <div 
            ref={storeContainerRef}
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={closeTooltip}
        >
             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center pt-[60px]">
                  <div className="w-full max-w-md space-y-8">

                      <div className="flex flex-col gap-4 mb-2">
                           <div className="flex justify-between items-center">
                                <button 
                                    onClick={onBack} 
                                    className="p-2 -ml-2 rounded-full hover:bg-stone-200 transition text-t-icon"
                                >
                                    <Icons.Back className="w-6 h-6" />
                                </button>
                                <div className="flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm border border-t-border">
                                    <span className="text-sm font-bold text-t-primary">{points}</span>
                                    <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                </div>
                           </div>
                           <div className="flex flex-col">
                               <h1 className="text-3xl font-black text-t-primary leading-tight">Store</h1>
                               <p className="text-t-secondary text-sm font-medium">Personalize your journey</p>
                           </div>
                      </div>

                      {/* SKILLS SECTION */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-3 ml-1">Skills</h2>
                          <div className="grid grid-cols-5 gap-x-2 gap-y-1">
                              {SKILLS.map(skill => {
                                  const isPurchased = purchasedSkills.includes(skill.id);
                                  const isEnabled = enabledSkills.includes(skill.id);
                                  const showTooltip = activeTooltipId === skill.id;

                                  return (
                                      <div key={skill.id} className="flex flex-col items-center relative">
                                          <div className="relative w-full">
                                              {showTooltip && <SkillTooltip text={skill.description} isClosing={isClosing} />}
                                              <button 
                                                  data-tooltip-trigger={isPurchased ? "true" : undefined}
                                                  onClick={(e) => handleSkillClick(e, skill)} 
                                                  className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all border border-t-border ${isPurchased ? (isEnabled ? 'bg-t-surface' : 'bg-t-surface-sec opacity-60 grayscale') : 'bg-t-surface active:scale-95'}`}
                                              >
                                                  {/* Icon Container: Flex-1 ensures it takes all available space above the bottom bar */}
                                                  <div className="flex-1 flex items-center justify-center">
                                                      <skill.icon className={`w-[34px] h-[34px] ${skill.class}`} />
                                                  </div>

                                                  {/* Bottom Bar: Static height, centers content vertically */}
                                                  <div className="h-7 bg-white dark:bg-stone-800 flex items-center justify-center shrink-0">
                                                      {!isPurchased ? (
                                                          <div className="flex items-center gap-0.5 pointer-events-none transform translate-y-[3px]">
                                                              <span className="text-sm font-bold text-stone-800 dark:text-white leading-none">{skill.cost}</span>
                                                              <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                          </div>
                                                      ) : (
                                                          <div 
                                                              onClick={(e) => handleToggleClick(e, skill.id)}
                                                              className="w-full h-full flex items-center justify-center cursor-pointer active:scale-95 transition-transform"
                                                              aria-label={`Toggle ${skill.name}`}
                                                          >
                                                               <div className={`w-12 h-6 rounded-full relative transition-colors duration-300 border-2 ${isEnabled ? 'bg-blue-500 border-blue-600' : 'bg-stone-200 dark:bg-stone-700 border-stone-300 dark:border-stone-600'}`}>
                                                                  <div className={`absolute top-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform duration-300 ease-out ${isEnabled ? 'translate-x-6' : 'translate-x-0.5'}`}></div>
                                                              </div>
                                                          </div>
                                                      )}
                                                  </div>
                                              </button>
                                          </div>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full mt-1">{skill.name}</span>
                                      </div>
                                  );
                              })}
                          </div>
                      </div>

                      {/* BACKGROUNDS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Backgrounds</h2>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Static</h3>
                              <div className="grid grid-cols-5 gap-2">{STATIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${!isSelected && bg.id === 'bg-default' ? 'ring-1 ring-inset ring-stone-900/10' : ''} ${!isPurchased ? 'opacity-90' : ''}`}>
                                              <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: bg.id === 'bg-default' ? 'calc(var(--overlay-opacity) * 0.6)' : 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              {isSelected && <div className="absolute inset-0 border-2 border-blue-500 rounded-xl z-20 pointer-events-none"></div>}
                                              {!isPurchased && (
                                                  <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                      <span className="text-sm font-bold text-t-primary leading-none">{bg.cost}</span>
                                                      <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                  </div>
                                              )}
                                          </button>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Atmosphere</h3>
                              <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${!isPurchased ? 'opacity-90' : ''}`}>
                                              <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              {isSelected && <div className="absolute inset-0 border-2 border-blue-500 rounded-xl z-20 pointer-events-none"></div>}
                                              {!isPurchased && (
                                                  <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                      <span className="text-sm font-bold text-t-primary leading-none">{bg.cost}</span>
                                                      <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                  </div>
                                              )}
                                          </button>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                      </div>

                      {/* SOUND PACKS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Sound Packs</h2>
                          <div className="grid grid-cols-5 gap-2">{SOUND_PACKS.map(pack => {
                              const isPurchased = purchasedSoundPacks.includes(pack.id);
                              const isSelected = selectedSoundPackId === pack.id;
                              const showTooltip = activeTooltipId === pack.id;

                              return (
                                  <div key={pack.id} className="flex flex-col items-center gap-1 relative">
                                      {showTooltip && <SkillTooltip text={pack.description} isClosing={isClosing} />}

                                      <button 
                                          data-tooltip-trigger={isPurchased && isSelected ? "true" : undefined}
                                          onClick={(e) => handleSoundPackClick(e, pack)} 
                                          className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all ${isSelected ? 'ring-2 ring-inset ring-blue-500 bg-t-surface scale-105 z-10' : 'bg-t-surface active:scale-95'}`}
                                      >
                                          {/* Decorative Background Gradient - Full Opacity for Vibrancy */}
                                          <div className={`absolute inset-0 bg-gradient-to-br ${pack.colorClass} opacity-80`} />

                                          {/* Icon Container: Centered in available space */}
                                          <div className="flex-1 flex items-center justify-center relative z-10">
                                              <pack.icon className={`w-8 h-8 ${pack.iconColor}`} />
                                          </div>

                                          {!isPurchased && (
                                              <div className="h-7 bg-white/60 dark:bg-stone-800/60 backdrop-blur-sm flex items-center justify-center gap-0.5 shrink-0 relative z-10">
                                                  <span className="text-sm font-bold text-t-primary leading-none">{pack.cost}</span>
                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                              </div>
                                          )}
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{pack.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>

                      {/* NUMBER COLORS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                          <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                              const isPurchased = purchasedNumberColors.includes(num.id);
                              const isSelected = selectedNumberColorId === num.id;
                              return (
                                  <div key={num.id} className="flex flex-col items-center gap-1">
                                      <button onClick={() => isPurchased ? onSelectNumberColor(num.id) : onPurchase(num, 'num')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 bg-t-surface ${isSelected ? 'ring-2 ring-inset ring-blue-500' : ''}`}>
                                          <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                              <span className={`text-3xl font-bold ${num.uiClass}`}>5</span>
                                          </div>
                                          {!isPurchased && (
                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                  <span className="text-sm font-bold text-t-primary leading-none">{num.cost}</span>
                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                              </div>
                                          )}
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{num.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

import { Difficulty, DiamondOffer } from '../types';
import { Icons } from '../components/ui/Icons';

const PACK_BASE_COSTS = {
    [Difficulty.SuperEasy]: 600,
    [Difficulty.Easy]: 700,
    [Difficulty.Normal]: 1200,
    [Difficulty.Hard]: 1500,
    [Difficulty.Intense]: 1800,
    [Difficulty.Impossible]: 2200,
};

export const getPackCost = (difficulty: Difficulty, packIndex: number): number => {
    let cost = PACK_BASE_COSTS[difficulty] || 0;

    // Pack 2 is the base (Levels 101-200). Pack 1 is included.
    if (packIndex <= 2) return cost;

    // Calculate cost for Pack 3+ iteratively
    for (let i = 3; i <= packIndex; i++) {
        // Increase by 15%
        const increased = cost * 1.15;
        // Round to nearest multiple of 10
        cost = Math.round(increased / 10) * 10;
    }

    return cost;
};

export const getDifficultyPoints = (diff: Difficulty) => {
    switch(diff) {
        case Difficulty.SuperEasy: return 5;
        case Difficulty.Easy: return 10;
        case Difficulty.Normal: return 15;
        case Difficulty.Hard: return 20;
        case Difficulty.Intense: return 30;
        case Difficulty.Impossible: return 50;
        default: return 0;
    }
};

