    const storeContainerRef = useRef<HTMLDivElement>(null);

    const closeTooltip = () => {
        if (!activeTooltipId || isClosing) return;
        setIsClosing(true);
        if (closeTimeoutRef.current) clearTimeout(closeTimeoutRef.current);
        closeTimeoutRef.current = setTimeout(() => {
            setActiveTooltipId(null);
            setIsClosing(false);
        }, 150);
    };

    // Global listener to handle "tapping anywhere else"
    useEffect(() => {
        const handleGlobalClick = (e: MouseEvent) => {
            if (!activeTooltipId) return;

            const target = e.target as HTMLElement;
            const isButton = target.closest('button');
            const isItemButton = isButton && (isButton.hasAttribute('data-tooltip-trigger'));

            if (!isItemButton) {
                closeTooltip();
            }
        };

        document.addEventListener('mousedown', handleGlobalClick);
        return () => document.removeEventListener('mousedown', handleGlobalClick);
    }, [activeTooltipId, isClosing]);

    const handleItemTooltip = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        sounds.playClick();

        if (activeTooltipId === id) {
            closeTooltip();
        } else {
            setActiveTooltipId(id);
            setIsClosing(false);
        }
    };

    const handleSoundPackClick = (e: React.MouseEvent, pack: typeof SOUND_PACKS[0]) => {
        const isPurchased = purchasedSoundPacks.includes(pack.id);
        const isSelected = selectedSoundPackId === pack.id;

        // Preview the sound whenever clicked
        sounds.playPreview(pack.id);

        if (!isPurchased) {
            onPurchase(pack, 'sound');
        } else {
            if (!isSelected) {
                onSelectSoundPack(pack.id);
                if (activeTooltipId === pack.id) closeTooltip();
            } else {
                handleItemTooltip(e, pack.id);
            }
        }
    };

    const handleSkillClick = (e: React.MouseEvent, skill: typeof SKILLS[0]) => {
        const isPurchased = purchasedSkills.includes(skill.id);

        if (!isPurchased) {
            onPurchase(skill, 'skill');
        } else {
            handleItemTooltip(e, skill.id);
        }
    };

    const handleToggleClick = (e: React.MouseEvent, skillId: string) => {
        e.stopPropagation();
        sounds.playClick();
        onToggleSkill(skillId);
    };

    return (
        <div 
            ref={storeContainerRef}
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={closeTooltip}
        >
             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center pt-[60px]">
                  <div className="w-full max-w-md space-y-8">

                      <div className="flex flex-col gap-4 mb-2">
                           <div className="flex justify-between items-center">
                                <button 
                                    onClick={onBack} 
                                    className="p-2 -ml-2 rounded-full hover:bg-stone-200 transition text-t-icon"
                                >
                                    <Icons.Back className="w-6 h-6" />
                                </button>
                                <div className="flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm border border-t-border">
                                    <span className="text-sm font-bold text-t-primary">{points}</span>
                                    <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                </div>
                           </div>
                           <div className="flex flex-col">
                               <h1 className="text-3xl font-black text-t-primary leading-tight">Store</h1>
                               <p className="text-t-secondary text-sm font-medium">Personalize your journey</p>
                           </div>
                      </div>

                      {/* SKILLS SECTION */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-3 ml-1">Skills</h2>
                          <div className="grid grid-cols-5 gap-x-2 gap-y-1">
                              {SKILLS.map(skill => {
                                  const isPurchased = purchasedSkills.includes(skill.id);
                                  const isEnabled = enabledSkills.includes(skill.id);
                                  const showTooltip = activeTooltipId === skill.id;

                                  return (
                                      <div key={skill.id} className="flex flex-col items-center relative">
                                          <div className="relative w-full">
                                              {showTooltip && <SkillTooltip text={skill.description} isClosing={isClosing} />}
                                              <button 
                                                  data-tooltip-trigger={isPurchased ? "true" : undefined}
                                                  onClick={(e) => handleSkillClick(e, skill)} 
                                                  className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all border border-t-border ${isPurchased ? (isEnabled ? 'bg-t-surface' : 'bg-t-surface-sec opacity-60 grayscale') : 'bg-t-surface active:scale-95'}`}
                                              >
                                                  {/* Icon Container: Flex-1 ensures it takes all available space above the bottom bar */}
                                                  <div className="flex-1 flex items-center justify-center">
                                                      <skill.icon className={`w-[34px] h-[34px] ${skill.class}`} />
                                                  </div>

                                                  {/* Bottom Bar: Static height, centers content vertically */}
                                                  <div className="h-7 bg-white dark:bg-stone-800 flex items-center justify-center shrink-0">
                                                      {!isPurchased ? (
                                                          <div className="flex items-center gap-0.5 pointer-events-none transform translate-y-[3px]">
                                                              <span className="text-sm font-bold text-stone-800 dark:text-white leading-none">{skill.cost}</span>
                                                              <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                          </div>
                                                      ) : (
                                                          <div 
                                                              onClick={(e) => handleToggleClick(e, skill.id)}
                                                              className="w-full h-full flex items-center justify-center cursor-pointer active:scale-95 transition-transform"
                                                              aria-label={`Toggle ${skill.name}`}
                                                          >
                                                               <div className={`w-12 h-6 rounded-full relative transition-colors duration-300 border-2 ${isEnabled ? 'bg-blue-500 border-blue-600' : 'bg-stone-200 dark:bg-stone-700 border-stone-300 dark:border-stone-600'}`}>
                                                                  <div className={`absolute top-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform duration-300 ease-out ${isEnabled ? 'translate-x-6' : 'translate-x-0.5'}`}></div>
                                                              </div>
                                                          </div>
                                                      )}
                                                  </div>
                                              </button>
                                          </div>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full mt-1">{skill.name}</span>
                                      </div>
                                  );
                              })}
                          </div>
                      </div>

                      {/* BACKGROUNDS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Backgrounds</h2>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Static</h3>
                              <div className="grid grid-cols-5 gap-2">{STATIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${!isSelected && bg.id === 'bg-default' ? 'ring-1 ring-inset ring-stone-900/10' : ''} ${!isPurchased ? 'opacity-90' : ''}`}>
                                              <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: bg.id === 'bg-default' ? 'calc(var(--overlay-opacity) * 0.6)' : 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              {isSelected && <div className="absolute inset-0 border-2 border-blue-500 rounded-xl z-20 pointer-events-none"></div>}
                                              {!isPurchased && (
                                                  <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                      <span className="text-sm font-bold text-t-primary leading-none">{bg.cost}</span>
                                                      <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                  </div>
                                              )}
                                          </button>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Atmosphere</h3>
                              <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 ${bg.class} ${!isPurchased ? 'opacity-90' : ''}`}>
                                              <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              {isSelected && <div className="absolute inset-0 border-2 border-blue-500 rounded-xl z-20 pointer-events-none"></div>}
                                              {!isPurchased && (
                                                  <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                      <span className="text-sm font-bold text-t-primary leading-none">{bg.cost}</span>
                                                      <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                                  </div>
                                              )}
                                          </button>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                      </div>

                      {/* SOUND PACKS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Sound Packs</h2>
                          <div className="grid grid-cols-5 gap-2">{SOUND_PACKS.map(pack => {
                              const isPurchased = purchasedSoundPacks.includes(pack.id);
                              const isSelected = selectedSoundPackId === pack.id;
                              const showTooltip = activeTooltipId === pack.id;

                              return (
                                  <div key={pack.id} className="flex flex-col items-center gap-1 relative">
                                      {showTooltip && <SkillTooltip text={pack.description} isClosing={isClosing} />}

                                      <button 
                                          data-tooltip-trigger={isPurchased && isSelected ? "true" : undefined}
                                          onClick={(e) => handleSoundPackClick(e, pack)} 
                                          className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all ${isSelected ? 'ring-2 ring-inset ring-blue-500 bg-t-surface scale-105 z-10' : 'bg-t-surface active:scale-95'}`}
                                      >
                                          {/* Increased Gradient Opacity for more color vibrancy */}
                                          <div className={`absolute inset-0 bg-gradient-to-br ${pack.colorClass} opacity-100`} />

                                          {/* Icon Container: Centered in available space */}
                                          <div className="flex-1 flex items-center justify-center relative z-10">
                                              <pack.icon className={`w-8 h-8 ${pack.iconColor}`} />
                                          </div>

                                          {!isPurchased && (
                                              <div className="h-7 bg-white/50 dark:bg-stone-800/50 backdrop-blur-sm flex items-center justify-center gap-0.5 shrink-0 relative z-10">
                                                  <span className="text-sm font-bold text-t-primary leading-none">{pack.cost}</span>
                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                              </div>
                                          )}
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{pack.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>

                      {/* NUMBER COLORS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                          <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                              const isPurchased = purchasedNumberColors.includes(num.id);
                              const isSelected = selectedNumberColorId === num.id;
                              return (
                                  <div key={num.id} className="flex flex-col items-center gap-1">
                                      <button onClick={() => isPurchased ? onSelectNumberColor(num.id) : onPurchase(num, 'num')} className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-center justify-center relative overflow-hidden transition-all active:scale-95 bg-t-surface ${isSelected ? 'ring-2 ring-inset ring-blue-500' : ''}`}>
                                          <div className={`flex items-center justify-center w-full h-full ${!isPurchased ? 'pb-4' : ''}`}>
                                              <span className={`text-3xl font-bold ${num.uiClass}`}>5</span>
                                          </div>
                                          {!isPurchased && (
                                              <div className="absolute bottom-0 inset-x-0 bg-t-surface py-1 flex items-center justify-center gap-0.5 z-10">
                                                  <span className="text-sm font-bold text-t-primary leading-none">{num.cost}</span>
                                                  <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                                              </div>
                                          )}
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{num.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { STATIC_BACKGROUNDS, DYNAMIC_BACKGROUNDS, NUMBER_COLORS, SKILLS, SOUND_PACKS } from '../../utils/constants';
import { SkillTooltip } from '../ui/SkillTooltip';

interface StoreScreenProps {
    points: number;
    onBack: () => void;
    purchasedSkills: string[];
    enabledSkills: string[];
    purchasedBackgrounds: string[];
    purchasedNumberColors: string[];
    purchasedSoundPacks: string[];
    selectedBackgroundId: string | null;
    selectedNumberColorId: string;
    selectedSoundPackId: string;
    onPurchase: (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => void;
    onSelectBackground: (id: string) => void;
    onSelectNumberColor: (id: string) => void;
    onSelectSoundPack: (id: string) => void;
    onToggleSkill: (id: string) => void;
}

export const StoreScreen: React.FC<StoreScreenProps> = ({
    points,
    onBack,
    purchasedSkills,
    enabledSkills,
    purchasedBackgrounds,
    purchasedNumberColors,
    purchasedSoundPacks,
    selectedBackgroundId,
    selectedNumberColorId,
    selectedSoundPackId,
    onPurchase,
    onSelectBackground,
    onSelectNumberColor,
    onSelectSoundPack,
    onToggleSkill
}) => {
    const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
    const [isClosing, setIsClosing] = useState(false);
    const closeTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const storeContainerRef = useRef<HTMLDivElement>(null);

    const closeTooltip = () => {
        if (!activeTooltipId || isClosing) return;
        setIsClosing(true);
        if (closeTimeoutRef.current) clearTimeout(closeTimeoutRef.current);
        closeTimeoutRef.current = setTimeout(() => {
            setActiveTooltipId(null);
            setIsClosing(false);
        }, 150);
    };

    // Global listener to handle "tapping anywhere else"
    useEffect(() => {
        const handleGlobalClick = (e: MouseEvent) => {
            if (!activeTooltipId) return;

            const target = e.target as HTMLElement;
            const isButton = target.closest('button');
            const isItemButton = isButton && (isButton.hasAttribute('data-tooltip-trigger'));

            if (!isItemButton) {
                closeTooltip();
            }
        };

        document.addEventListener('mousedown', handleGlobalClick);
        return () => document.removeEventListener('mousedown', handleGlobalClick);
    }, [activeTooltipId, isClosing]);

    const handleItemTooltip = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        sounds.playClick();

        if (activeTooltipId === id) {
            closeTooltip();
        } else {
            setActiveTooltipId(id);
            setIsClosing(false);
        }
    };

    const handleSoundPackClick = (e: React.MouseEvent, pack: typeof SOUND_PACKS[0]) => {
        const isPurchased = purchasedSoundPacks.includes(pack.id);
        const isSelected = selectedSoundPackId === pack.id;

        // Preview the sound whenever clicked
        sounds.playPreview(pack.id);

        if (!isPurchased) {
            onPurchase(pack, 'sound');
        } else {
            if (!isSelected) {
                onSelectSoundPack(pack.id);
                if (activeTooltipId === pack.id) closeTooltip();
            } else {
                handleItemTooltip(e, pack.id);
            }
        }
    };

    const handleSkillClick = (e: React.MouseEvent, skill: typeof SKILLS[0]) => {
        const isPurchased = purchasedSkills.includes(skill.id);

        if (!isPurchased) {
            onPurchase(skill, 'skill');
        } else {
            handleItemTooltip(e, skill.id);
        }
    };

    const handleToggleClick = (e: React.MouseEvent, skillId: string) => {
        e.stopPropagation();
        sounds.playClick();
        onToggleSkill(skillId);
    };

    // Shared Price Footer component for consistency
    const ItemFooter = ({ isPurchased, isSelected, cost, isSkill = false, skillEnabled = false, onToggle }: any) => {
        if (!isPurchased) {
            return (
                <div className="h-8 bg-white/80 dark:bg-stone-800/80 backdrop-blur-sm border-t border-t-border/50 flex items-center justify-center gap-0.5 shrink-0 relative z-10">
                    <span className="text-sm font-black text-stone-900 dark:text-white leading-none pt-0.5">{cost}</span>
                    <Icons.Diamond className="w-3.5 h-3.5 text-blue-500 fill-current" />
                </div>
            );
        }

        if (isSkill) {
            return (
                <div 
                    onClick={onToggle}
                    className="h-8 bg-white dark:bg-stone-800 border-t border-t-border flex items-center justify-center shrink-0 cursor-pointer active:scale-95 transition-transform"
                >
                    <div className={`w-12 h-6 rounded-full relative transition-colors duration-300 border-2 ${skillEnabled ? 'bg-blue-500 border-blue-600' : 'bg-stone-200 dark:bg-stone-700 border-stone-300 dark:border-stone-600'}`}>
                        <div className={`absolute top-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform duration-300 ease-out ${skillEnabled ? 'translate-x-6' : 'translate-x-0.5'}`}></div>
                    </div>
                </div>
            );
        }

        return (
            <div className={`h-8 flex items-center justify-center shrink-0 relative z-10 transition-colors ${isSelected ? 'bg-blue-500/10 dark:bg-blue-500/20' : 'bg-white/40 dark:bg-stone-800/40 border-t border-t-border/50'}`}>
                {isSelected ? (
                    <Icons.Check className="w-4 h-4 text-blue-500 stroke-[4]" />
                ) : (
                    <span className="text-[10px] font-black text-stone-400 dark:text-stone-500 uppercase tracking-tighter pt-0.5">Select</span>
                )}
            </div>
        );
    };

    return (
        <div 
            ref={storeContainerRef}
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={closeTooltip}
        >
             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center pt-[60px]">
                  <div className="w-full max-w-md space-y-8">

                      <div className="flex flex-col gap-4 mb-2">
                           <div className="flex justify-between items-center">
                                <button 
                                    onClick={onBack} 
                                    className="p-2 -ml-2 rounded-full hover:bg-stone-200 transition text-t-icon"
                                >
                                    <Icons.Back className="w-6 h-6" />
                                </button>
                                <div className="flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm border border-t-border">
                                    <span className="text-sm font-bold text-t-primary">{points}</span>
                                    <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                </div>
                           </div>
                           <div className="flex flex-col">
                               <h1 className="text-3xl font-black text-t-primary leading-tight">Store</h1>
                               <p className="text-t-secondary text-sm font-medium">Personalize your journey</p>
                           </div>
                      </div>

                      {/* SKILLS SECTION */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-3 ml-1">Skills</h2>
                          <div className="grid grid-cols-5 gap-x-2 gap-y-1">
                              {SKILLS.map(skill => {
                                  const isPurchased = purchasedSkills.includes(skill.id);
                                  const isEnabled = enabledSkills.includes(skill.id);
                                  const showTooltip = activeTooltipId === skill.id;

                                  return (
                                      <div key={skill.id} className="flex flex-col items-center relative">
                                          <div className="relative w-full">
                                              {showTooltip && <SkillTooltip text={skill.description} isClosing={isClosing} />}
                                              <button 
                                                  data-tooltip-trigger={isPurchased ? "true" : undefined}
                                                  onClick={(e) => handleSkillClick(e, skill)} 
                                                  className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all border border-t-border ${isPurchased ? (isEnabled ? 'bg-t-surface' : 'bg-t-surface-sec opacity-60 grayscale') : 'bg-t-surface active:scale-95'}`}
                                              >
                                                  <div className="flex-1 flex items-center justify-center">
                                                      <skill.icon className={`w-[34px] h-[34px] ${skill.class}`} />
                                                  </div>
                                                  <ItemFooter 
                                                      isPurchased={isPurchased} 
                                                      isSkill={true} 
                                                      skillEnabled={isEnabled} 
                                                      cost={skill.cost} 
                                                      onToggle={(e: any) => handleToggleClick(e, skill.id)}
                                                  />
                                              </button>
                                          </div>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full mt-1">{skill.name}</span>
                                      </div>
                                  );
                              })}
                          </div>
                      </div>

                      {/* BACKGROUNDS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Backgrounds</h2>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Static</h3>
                              <div className="grid grid-cols-5 gap-2">{STATIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button 
                                              onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} 
                                              className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-white dark:bg-stone-800 ${isSelected ? 'ring-2 ring-inset ring-blue-500' : 'border border-t-border'}`}
                                          >
                                              <div className={`flex-1 relative overflow-hidden ${bg.class}`}>
                                                   <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: bg.id === 'bg-default' ? 'calc(var(--overlay-opacity) * 0.6)' : 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              </div>
                                              <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={bg.cost} />
                                          </button>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Atmosphere</h3>
                              <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button 
                                              onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} 
                                              className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-white dark:bg-stone-800 ${isSelected ? 'ring-2 ring-inset ring-blue-500' : 'border border-t-border'}`}
                                          >
                                              <div className={`flex-1 relative overflow-hidden ${bg.class}`}>
                                                   <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              </div>
                                              <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={bg.cost} />
                                          </button>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                      </div>

                      {/* SOUND PACKS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Sound Packs</h2>
                          <div className="grid grid-cols-5 gap-2">{SOUND_PACKS.map(pack => {
                              const isPurchased = purchasedSoundPacks.includes(pack.id);
                              const isSelected = selectedSoundPackId === pack.id;
                              const showTooltip = activeTooltipId === pack.id;

                              return (
                                  <div key={pack.id} className="flex flex-col items-center gap-1 relative">
                                      {showTooltip && <SkillTooltip text={pack.description} isClosing={isClosing} />}

                                      <button 
                                          data-tooltip-trigger={isPurchased && isSelected ? "true" : undefined}
                                          onClick={(e) => handleSoundPackClick(e, pack)} 
                                          className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all ${isSelected ? 'ring-2 ring-inset ring-blue-500 bg-t-surface scale-105 z-10' : 'bg-t-surface active:scale-95 border border-t-border'}`}
                                      >
                                          <div className={`flex-1 flex items-center justify-center relative z-10 overflow-hidden`}>
                                              <div className={`absolute inset-0 bg-gradient-to-br ${pack.colorClass} opacity-100`} />
                                              <pack.icon className={`w-8 h-8 ${pack.iconColor} relative z-20`} />
                                          </div>
                                          <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={pack.cost} />
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{pack.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>

                      {/* NUMBER COLORS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                          <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                              const isPurchased = purchasedNumberColors.includes(num.id);
                              const isSelected = selectedNumberColorId === num.id;
                              return (
                                  <div key={num.id} className="flex flex-col items-center gap-1">
                                      <button 
                                          onClick={() => isPurchased ? onSelectNumberColor(num.id) : onPurchase(num, 'num')} 
                                          className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-t-surface ${isSelected ? 'ring-2 ring-inset ring-blue-500' : 'border border-t-border'}`}
                                      >
                                          <div className="flex-1 flex items-center justify-center w-full">
                                              <span className={`text-3xl font-bold ${num.uiClass}`}>5</span>
                                          </div>
                                          <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={num.cost} />
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{num.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { STATIC_BACKGROUNDS, DYNAMIC_BACKGROUNDS, NUMBER_COLORS, SKILLS, SOUND_PACKS } from '../../utils/constants';
import { SkillTooltip } from '../ui/SkillTooltip';

interface StoreScreenProps {
    points: number;
    onBack: () => void;
    purchasedSkills: string[];
    enabledSkills: string[];
    purchasedBackgrounds: string[];
    purchasedNumberColors: string[];
    purchasedSoundPacks: string[];
    selectedBackgroundId: string | null;
    selectedNumberColorId: string;
    selectedSoundPackId: string;
    onPurchase: (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => void;
    onSelectBackground: (id: string) => void;
    onSelectNumberColor: (id: string) => void;
    onSelectSoundPack: (id: string) => void;
    onToggleSkill: (id: string) => void;
}

export const StoreScreen: React.FC<StoreScreenProps> = ({
    points,
    onBack,
    purchasedSkills,
    enabledSkills,
    purchasedBackgrounds,
    purchasedNumberColors,
    purchasedSoundPacks,
    selectedBackgroundId,
    selectedNumberColorId,
    selectedSoundPackId,
    onPurchase,
    onSelectBackground,
    onSelectNumberColor,
    onSelectSoundPack,
    onToggleSkill
}) => {
    const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
    const [isClosing, setIsClosing] = useState(false);
    const closeTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const storeContainerRef = useRef<HTMLDivElement>(null);

    const closeTooltip = () => {
        if (!activeTooltipId || isClosing) return;
        setIsClosing(true);
        if (closeTimeoutRef.current) clearTimeout(closeTimeoutRef.current);
        closeTimeoutRef.current = setTimeout(() => {
            setActiveTooltipId(null);
            setIsClosing(false);
        }, 150);
    };

    // Global listener to handle "tapping anywhere else"
    useEffect(() => {
        const handleGlobalClick = (e: MouseEvent) => {
            if (!activeTooltipId) return;

            const target = e.target as HTMLElement;
            const isButton = target.closest('button');
            const isItemButton = isButton && (isButton.hasAttribute('data-tooltip-trigger'));

            if (!isItemButton) {
                closeTooltip();
            }
        };

        document.addEventListener('mousedown', handleGlobalClick);
        return () => document.removeEventListener('mousedown', handleGlobalClick);
    }, [activeTooltipId, isClosing]);

    const handleItemTooltip = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        sounds.playClick();

        if (activeTooltipId === id) {
            closeTooltip();
        } else {
            setActiveTooltipId(id);
            setIsClosing(false);
        }
    };

    const handleSoundPackClick = (e: React.MouseEvent, pack: typeof SOUND_PACKS[0]) => {
        const isPurchased = purchasedSoundPacks.includes(pack.id);
        const isSelected = selectedSoundPackId === pack.id;

        // Preview the sound whenever clicked
        sounds.playPreview(pack.id);

        if (!isPurchased) {
            onPurchase(pack, 'sound');
        } else {
            if (!isSelected) {
                onSelectSoundPack(pack.id);
                if (activeTooltipId === pack.id) closeTooltip();
            } else {
                handleItemTooltip(e, pack.id);
            }
        }
    };

    const handleSkillClick = (e: React.MouseEvent, skill: typeof SKILLS[0]) => {
        const isPurchased = purchasedSkills.includes(skill.id);

        if (!isPurchased) {
            onPurchase(skill, 'skill');
        } else {
            handleItemTooltip(e, skill.id);
        }
    };

    const handleToggleClick = (e: React.MouseEvent, skillId: string) => {
        e.stopPropagation();
        sounds.playClick();
        onToggleSkill(skillId);
    };

    // Shared Price Footer component for consistency
    const ItemFooter = ({ isPurchased, isSelected, cost, isSkill = false, skillEnabled = false, onToggle }: any) => {
        if (!isPurchased) {
            return (
                <div className="h-8 bg-white/80 dark:bg-stone-800/80 backdrop-blur-sm border-t border-t-border flex items-center justify-center gap-0.5 shrink-0 relative z-10">
                    <span className="text-sm font-black text-stone-900 dark:text-white leading-none pt-0.5">{cost}</span>
                    <Icons.Diamond className="w-3.5 h-3.5 text-blue-500 fill-current" />
                </div>
            );
        }

        if (isSkill) {
            return (
                <div 
                    onClick={onToggle}
                    className={`h-8 border-t flex items-center justify-center shrink-0 cursor-pointer active:scale-95 transition-all ${skillEnabled ? 'border-transparent bg-transparent' : 'border-t-border bg-white dark:bg-stone-800'}`}
                >
                    <div className={`w-12 h-6 rounded-full relative transition-colors duration-300 border-2 ${skillEnabled ? 'bg-blue-500 border-blue-600' : 'bg-stone-200 dark:bg-stone-700 border-stone-300 dark:border-stone-600'}`}>
                        <div className={`absolute top-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform duration-300 ease-out ${skillEnabled ? 'translate-x-6' : 'translate-x-0.5'}`}></div>
                    </div>
                </div>
            );
        }

        return (
            <div className={`h-8 flex items-center justify-center shrink-0 relative z-10 transition-all ${isSelected ? 'bg-transparent' : 'bg-white/40 dark:bg-stone-800/40 border-t border-t-border'}`}>
                {isSelected ? (
                    <Icons.Check className="w-4 h-4 text-blue-500 stroke-[4]" />
                ) : (
                    <span className="text-[10px] font-black text-stone-400 dark:text-stone-500 uppercase tracking-tighter pt-0.5">Select</span>
                )}
            </div>
        );
    };

    return (
        <div 
            ref={storeContainerRef}
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={closeTooltip}
        >
             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center pt-[60px]">
                  <div className="w-full max-w-md space-y-8">

                      <div className="flex flex-col gap-4 mb-2">
                           <div className="flex justify-between items-center">
                                <button 
                                    onClick={onBack} 
                                    className="p-2 -ml-2 rounded-full hover:bg-stone-200 transition text-t-icon"
                                >
                                    <Icons.Back className="w-6 h-6" />
                                </button>
                                <div className="flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm border border-t-border">
                                    <span className="text-sm font-bold text-t-primary">{points}</span>
                                    <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                                </div>
                           </div>
                           <div className="flex flex-col">
                               <h1 className="text-3xl font-black text-t-primary leading-tight">Store</h1>
                               <p className="text-t-secondary text-sm font-medium">Personalize your journey</p>
                           </div>
                      </div>

                      {/* SKILLS SECTION */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-3 ml-1">Skills</h2>
                          <div className="grid grid-cols-5 gap-x-2 gap-y-1">
                              {SKILLS.map(skill => {
                                  const isPurchased = purchasedSkills.includes(skill.id);
                                  const isEnabled = enabledSkills.includes(skill.id);
                                  const showTooltip = activeTooltipId === skill.id;

                                  return (
                                      <div key={skill.id} className="flex flex-col items-center relative">
                                          <div className="relative w-full">
                                              {showTooltip && <SkillTooltip text={skill.description} isClosing={isClosing} />}
                                              <button 
                                                  data-tooltip-trigger={isPurchased ? "true" : undefined}
                                                  onClick={(e) => handleSkillClick(e, skill)} 
                                                  className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all border-2 ${isPurchased && isEnabled ? 'border-blue-500 bg-blue-50/10 dark:bg-blue-900/10 scale-105 z-10' : 'border-t-border bg-t-surface active:scale-95'} ${isPurchased && !isEnabled ? 'opacity-60 grayscale' : ''}`}
                                              >
                                                  <div className="flex-1 flex items-center justify-center">
                                                      <skill.icon className={`w-[34px] h-[34px] ${skill.class}`} />
                                                  </div>
                                                  <ItemFooter 
                                                      isPurchased={isPurchased} 
                                                      isSkill={true} 
                                                      skillEnabled={isEnabled} 
                                                      cost={skill.cost} 
                                                      onToggle={(e: any) => handleToggleClick(e, skill.id)}
                                                  />
                                              </button>
                                          </div>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full mt-1">{skill.name}</span>
                                      </div>
                                  );
                              })}
                          </div>
                      </div>

                      {/* BACKGROUNDS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Backgrounds</h2>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Static</h3>
                              <div className="grid grid-cols-5 gap-2">{STATIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button 
                                              onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} 
                                              className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-white dark:bg-stone-800 border-2 ${isSelected ? 'border-blue-500 bg-blue-50/10 dark:bg-blue-900/10 scale-105 z-10' : 'border-t-border'}`}
                                          >
                                              <div className={`flex-1 relative overflow-hidden ${bg.class}`}>
                                                   <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: bg.id === 'bg-default' ? 'calc(var(--overlay-opacity) * 0.6)' : 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              </div>
                                              <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={bg.cost} />
                                          </button>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Atmosphere</h3>
                              <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1">
                                          <button 
                                              onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} 
                                              className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-white dark:bg-stone-800 border-2 ${isSelected ? 'border-blue-500 bg-blue-50/10 dark:bg-blue-900/10 scale-105 z-10' : 'border-t-border'}`}
                                          >
                                              <div className={`flex-1 relative overflow-hidden ${bg.class}`}>
                                                   <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              </div>
                                              <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={bg.cost} />
                                          </button>
                                          <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                      </div>

                      {/* SOUND PACKS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Sound Packs</h2>
                          <div className="grid grid-cols-5 gap-2">{SOUND_PACKS.map(pack => {
                              const isPurchased = purchasedSoundPacks.includes(pack.id);
                              const isSelected = selectedSoundPackId === pack.id;
                              const showTooltip = activeTooltipId === pack.id;

                              return (
                                  <div key={pack.id} className="flex flex-col items-center gap-1 relative">
                                      {showTooltip && <SkillTooltip text={pack.description} isClosing={isClosing} />}

                                      <button 
                                          data-tooltip-trigger={isPurchased && isSelected ? "true" : undefined}
                                          onClick={(e) => handleSoundPackClick(e, pack)} 
                                          className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all border-2 ${isSelected ? 'border-blue-500 bg-blue-50/10 dark:bg-blue-900/10 scale-105 z-10' : 'border-t-border bg-t-surface active:scale-95'}`}
                                      >
                                          <div className={`flex-1 flex items-center justify-center relative z-10 overflow-hidden`}>
                                              <div className={`absolute inset-0 bg-gradient-to-br ${pack.colorClass} opacity-100`} />
                                              <pack.icon className={`w-8 h-8 ${pack.iconColor} relative z-20`} />
                                          </div>
                                          <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={pack.cost} />
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{pack.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>

                      {/* NUMBER COLORS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                          <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                              const isPurchased = purchasedNumberColors.includes(num.id);
                              const isSelected = selectedNumberColorId === num.id;
                              return (
                                  <div key={num.id} className="flex flex-col items-center gap-1">
                                      <button 
                                          onClick={() => isPurchased ? onSelectNumberColor(num.id) : onPurchase(num, 'num')} 
                                          className={`w-full aspect-square rounded-xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-t-surface border-2 ${isSelected ? 'border-blue-500 bg-blue-50/10 dark:bg-blue-900/10 scale-105 z-10' : 'border-t-border'}`}
                                      >
                                          <div className="flex-1 flex items-center justify-center w-full">
                                              <span className={`text-3xl font-bold ${num.uiClass}`}>5</span>
                                          </div>
                                          <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={num.cost} />
                                      </button>
                                      <span className="text-[10px] font-bold text-t-secondary text-center truncate w-full">{num.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { STATIC_BACKGROUNDS, DYNAMIC_BACKGROUNDS, NUMBER_COLORS, SKILLS, SOUND_PACKS } from '../../utils/constants';
import { SkillTooltip } from '../ui/SkillTooltip';

interface StoreScreenProps {
    points: number;
    onBack: () => void;
    purchasedSkills: string[];
    enabledSkills: string[];
    purchasedBackgrounds: string[];
    purchasedNumberColors: string[];
    purchasedSoundPacks: string[];
    selectedBackgroundId: string | null;
    selectedNumberColorId: string;
    selectedSoundPackId: string;
    onPurchase: (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => void;
    onSelectBackground: (id: string) => void;
    onSelectNumberColor: (id: string) => void;
    onSelectSoundPack: (id: string) => void;
    onToggleSkill: (id: string) => void;
}

export const StoreScreen: React.FC<StoreScreenProps> = ({
    points,
    onBack,
    purchasedSkills,
    enabledSkills,
    purchasedBackgrounds,
    purchasedNumberColors,
    purchasedSoundPacks,
    selectedBackgroundId,
    selectedNumberColorId,
    selectedSoundPackId,
    onPurchase,
    onSelectBackground,
    onSelectNumberColor,
    onSelectSoundPack,
    onToggleSkill
}) => {
    const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);
    const [isClosing, setIsClosing] = useState(false);
    const closeTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const storeContainerRef = useRef<HTMLDivElement>(null);

    const closeTooltip = () => {
        if (!activeTooltipId || isClosing) return;
        setIsClosing(true);
        if (closeTimeoutRef.current) clearTimeout(closeTimeoutRef.current);
        closeTimeoutRef.current = setTimeout(() => {
            setActiveTooltipId(null);
            setIsClosing(false);
        }, 150);
    };

    // Global listener to handle "tapping anywhere else"
    useEffect(() => {
        const handleGlobalClick = (e: MouseEvent) => {
            if (!activeTooltipId) return;

            const target = e.target as HTMLElement;
            const isButton = target.closest('button');
            const isItemButton = isButton && (isButton.hasAttribute('data-tooltip-trigger'));

            if (!isItemButton) {
                closeTooltip();
            }
        };

        document.addEventListener('mousedown', handleGlobalClick);
        return () => document.removeEventListener('mousedown', handleGlobalClick);
    }, [activeTooltipId, isClosing]);

    const handleItemTooltip = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        sounds.playClick();

        if (activeTooltipId === id) {
            closeTooltip();
        } else {
            setActiveTooltipId(id);
            setIsClosing(false);
        }
    };

    const handleSoundPackClick = (e: React.MouseEvent, pack: typeof SOUND_PACKS[0]) => {
        const isPurchased = purchasedSoundPacks.includes(pack.id);
        const isSelected = selectedSoundPackId === pack.id;

        // Preview the sound whenever clicked
        sounds.playPreview(pack.id);

        if (!isPurchased) {
            onPurchase(pack, 'sound');
        } else {
            if (!isSelected) {
                onSelectSoundPack(pack.id);
                if (activeTooltipId === pack.id) closeTooltip();
            } else {
                handleItemTooltip(e, pack.id);
            }
        }
    };

    const handleSkillClick = (e: React.MouseEvent, skill: typeof SKILLS[0]) => {
        const isPurchased = purchasedSkills.includes(skill.id);

        if (!isPurchased) {
            onPurchase(skill, 'skill');
        } else {
            handleItemTooltip(e, skill.id);
        }
    };

    const handleToggleClick = (e: React.MouseEvent, skillId: string) => {
        e.stopPropagation();
        sounds.playClick();
        onToggleSkill(skillId);
    };

    // Shared Price Footer component for consistency
    const ItemFooter = ({ isPurchased, isSelected, cost, isSkill = false, skillEnabled = false, onToggle }: any) => {
        // If not purchased, always show price
        if (!isPurchased) {
            return (
                <div className="h-8 bg-white/80 dark:bg-stone-800/80 backdrop-blur-sm border-t border-t-border flex items-center justify-center gap-0.5 shrink-0 relative z-10">
                    <span className="text-sm font-black text-stone-900 dark:text-white leading-none pt-0.5">{cost}</span>
                    <Icons.Diamond className="w-3.5 h-3.5 text-blue-500 fill-current" />
                </div>
            );
        }

        // Skills still need a toggle footer
        if (isSkill) {
            return (
                <div 
                    onClick={onToggle}
                    className={`h-8 border-t flex items-center justify-center shrink-0 cursor-pointer active:scale-95 transition-all ${skillEnabled ? 'border-transparent bg-transparent' : 'border-t-border bg-white dark:bg-stone-800'}`}
                >
                    <div className={`w-12 h-6 rounded-full relative transition-colors duration-300 border-2 ${skillEnabled ? 'bg-blue-500 border-blue-600' : 'bg-stone-200 dark:bg-stone-700 border-stone-300 dark:border-stone-600'}`}>
                        <div className={`absolute top-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform duration-300 ease-out ${skillEnabled ? 'translate-x-6' : 'translate-x-0.5'}`}></div>
                    </div>
                </div>
            );
        }

        // For backgrounds, sounds, and numbers: remove footer entirely once bought
        return null;
    };

    return (
        <div 
            ref={storeContainerRef}
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={closeTooltip}
        >
