import { Board } from '../types';

export interface ReplayMove {
  row: number;
  col: number;
  value: number;
  t?: number; // Relative time in milliseconds or timer seconds
}

// Refined Audio Synthesis Helper with precise scheduling support
function createReplayAudio(ctx: AudioContext, dest: MediaStreamAudioDestinationNode) {
    // 1. Standard Move Pop (Lower, accumulation feel)
    const playPop = (progress: number, t: number) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(dest);

        // Pitch scale: Exponential from C5 to C6 based on progress
        const freq = 523.25 * Math.pow(2, progress);
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, t);

        // Crisp, audible pop
        gain.gain.setValueAtTime(0, t);
        gain.gain.linearRampToValueAtTime(0.5, t + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);

        osc.start(t);
        osc.stop(t + 0.1);
    };

    // 2. Subtle Premium Victory (Soft Chord Swell)
    const playVictory = (t: number) => {
        const notes = [523.25, 659.25, 783.99, 987.77];

        notes.forEach((freq, i) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain);
            gain.connect(dest);

            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, t);

            const start = t + (i * 0.05); 

            gain.gain.setValueAtTime(0, start);
            gain.gain.linearRampToValueAtTime(0.15, start + 0.1); 
            gain.gain.exponentialRampToValueAtTime(0.001, start + 2.0); 

            osc.start(start);
            osc.stop(start + 2.5);
        });
    };

    return { playPop, playVictory };
}

export async function generateReplayVideo(
  initialBoard: Board,
  moves: ReplayMove[],
  difficulty: string,
  levelId: number,
  isDark: boolean,
  totalTime: number
): Promise<string | null> {
  if (typeof document === 'undefined') return null;

  const canvas = document.createElement('canvas');
  const size = 1080;
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  // Initialize Audio
  const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();

  if (audioCtx.state === 'suspended') {
      try {
        await audioCtx.resume();
      } catch (e) {
        console.warn("Could not resume audio context", e);
      }
  }

  const dest = audioCtx.createMediaStreamDestination();
  const { playPop, playVictory } = createReplayAudio(audioCtx, dest);

  // Configuration
  const FPS = 30;
  const INTRO_MS = 800;
  const OUTRO_MS = 2500;

  // SEQUENTIAL TIMING (Fix for sync issues caused by long pauses)
  // We allocate a steady cadence for moves regardless of when they happened.
  // This creates a "Zen" flow that is always satisfying to watch.
  const FRAMES_PER_MOVE = 4; // Fast and snappy
  const FILL_FRAMES = Math.max(60, moves.length * FRAMES_PER_MOVE);

  const INTRO_FRAMES = Math.floor((INTRO_MS / 1000) * FPS);
  const OUTRO_FRAMES = Math.floor((OUTRO_MS / 1000) * FPS);
  const TOTAL_FRAMES = INTRO_FRAMES + FILL_FRAMES + OUTRO_FRAMES;

  const c = {
    bg: isDark ? '#1c1917' : '#fafaf9',
    boardBg: isDark ? '#292524' : '#ffffff',
    gridLineThin: isDark ? '#57534e' : '#e7e5e4',
    gridLineThick: isDark ? '#a8a29e' : '#78716c',
    textFixed: isDark ? '#f5f5f4' : '#292524',
    textInput: '#3b82f6',
    successBorder: '#10b981',
    watermark: isDark ? '#57534e' : '#a8a29e',
  };

  const padding = 120;
  const boardSize = size - (padding * 2);
  const cellSize = boardSize / 9;
  const startX = padding;
  const startY = padding;

  const moveCount = moves.length;
  const moveFrames = new Int32Array(moveCount);

  // Distribute moves evenly across the fill time
  for (let i = 0; i < moveCount; i++) {
      moveFrames[i] = INTRO_FRAMES + (i * FRAMES_PER_MOVE);
  }

  const formatTime = (seconds: number) => {
      const total = Math.floor(seconds);
      const mins = Math.floor(total / 60);
      const secs = total % 60;
      return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const drawBoard = (frame: number) => {
      ctx.fillStyle = c.bg;
      ctx.fillRect(0, 0, size, size);

      let globalOpacity = 1;
      let scale = 1;
      if (frame < INTRO_FRAMES) {
          const t = frame / INTRO_FRAMES;
          globalOpacity = t;
          scale = 0.95 + (0.05 * t);
      }

      ctx.save();
      ctx.translate(size/2, size/2);
      ctx.scale(scale, scale);
      ctx.translate(-size/2, -size/2);
      ctx.globalAlpha = globalOpacity;

      // Header - Level Title
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = c.textFixed;
      ctx.font = 'bold 40px "Outfit", sans-serif';
      const titleY = padding / 2;
      ctx.fillText(`${difficulty.toUpperCase()} • LEVEL ${levelId}`, size/2, titleY - 14);

      // Header - Timer (Linearly interpolated to match video flow)
      let currentSeconds = totalTime;
      if (frame < INTRO_FRAMES) {
          currentSeconds = 0;
      } else if (frame < (INTRO_FRAMES + FILL_FRAMES)) {
          const progress = (frame - INTRO_FRAMES) / FILL_FRAMES;
          currentSeconds = totalTime * progress;
      }

      ctx.font = 'bold 40px "Outfit", sans-serif';
      ctx.fillText(formatTime(currentSeconds), size/2, titleY + 31);

      // Watermark
      ctx.fillStyle = c.watermark;
      ctx.font = '500 30px "Outfit", sans-serif';
      ctx.fillText("OKU: SUDOKU", size/2, size - (padding / 2));

      // Board Background
      ctx.shadowColor = "rgba(0,0,0,0.1)";
      ctx.shadowBlur = 30;
      ctx.shadowOffsetY = 10;
      ctx.fillStyle = c.boardBg;
      const r = 32;
      ctx.beginPath();
      ctx.roundRect(startX, startY, boardSize, boardSize, r);
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.shadowOffsetY = 0;

      // Grid
      ctx.save();
      ctx.beginPath();
      ctx.roundRect(startX, startY, boardSize, boardSize, r);
      ctx.clip();

      ctx.lineCap = 'butt';
      for (let i = 1; i < 9; i++) {
          const pos = i * cellSize;
          const isThick = i % 3 === 0;
          ctx.lineWidth = isThick ? 6 : 2;
          ctx.strokeStyle = isThick ? c.gridLineThick : c.gridLineThin;

          ctx.beginPath();
          ctx.moveTo(startX + pos, startY);
          ctx.lineTo(startX + pos, startY + boardSize);
          ctx.stroke();

          ctx.beginPath();
          ctx.moveTo(startX, startY + pos);
          ctx.lineTo(startX + boardSize, startY + pos);
          ctx.stroke();
      }
      ctx.restore();

      // Fixed Nums
      ctx.font = `600 ${cellSize * 0.6}px "Outfit", sans-serif`;
      ctx.fillStyle = c.textFixed;

      initialBoard.forEach(row => {
          row.forEach(cell => {
              if (cell.isFixed && cell.value) {
                  const cx = startX + (cell.col * cellSize) + (cellSize / 2);
                  const cy = startY + (cell.row * cellSize) + (cellSize / 2);
                  ctx.fillText(cell.value.toString(), cx, cy);
              }
          });
      });

      // Animated Moves
      for (let i = 0; i < moveCount; i++) {
          const startFrame = moveFrames[i];
          if (frame >= startFrame) {
             const m = moves[i];
             const cx = startX + (m.col * cellSize) + (cellSize / 2);
             const cy = startY + (m.row * cellSize) + (cellSize / 2);

             let scale = 1;
             let alpha = 1;

             // Pop animation
             if (frame < startFrame + 5) {
                 const t = (frame - startFrame) / 5;
                 scale = 0.5 + (0.7 * t); // Overshoot
             } else if (frame < startFrame + 8) {
                 scale = 1.2 - (0.2 * ((frame - (startFrame + 5)) / 3)); // Settle
             }

             ctx.save();
             ctx.translate(cx, cy);
             ctx.scale(scale, scale);
             ctx.globalAlpha = alpha;
             ctx.fillStyle = c.textInput;
             ctx.fillText(m.value.toString(), 0, 0);
             ctx.restore();
          }
      }

      ctx.restore();

      // Victory Overlay (Fade In)
      if (frame > INTRO_FRAMES + FILL_FRAMES) {
          const t = Math.min(1, (frame - (INTRO_FRAMES + FILL_FRAMES)) / 20);

          // Green Border Glow
          ctx.lineWidth = 8;
          ctx.strokeStyle = `rgba(16, 185, 129, ${t})`; // Emerald 500
          ctx.beginPath();
          ctx.roundRect(startX - 4, startY - 4, boardSize + 8, boardSize + 8, r + 4);
          ctx.stroke();
      }
  };

  const stream = canvas.captureStream(FPS);
  const audioStream = dest.stream;
  const combinedStream = new MediaStream([
      ...stream.getVideoTracks(),
      ...audioStream.getAudioTracks()
  ]);

  const recorder = new MediaRecorder(combinedStream, {
      mimeType: 'video/webm;codecs=vp9',
      videoBitsPerSecond: 2500000 
  });

  const chunks: Blob[] = [];
  recorder.ondataavailable = (e) => {
      if (e.data.size > 0) chunks.push(e.data);
  };

  return new Promise((resolve) => {
      recorder.onstop = () => {
          const blob = new Blob(chunks, { type: 'video/webm' });
          const url = URL.createObjectURL(blob);
          audioCtx.close();
          resolve(url);
      };

      recorder.start();

      let frame = 0;
      let lastMoveIndex = -1;

      const render = () => {
          if (frame >= TOTAL_FRAMES) {
              recorder.stop();
              return;
          }

          drawBoard(frame);

          // Trigger Audio Events
          for (let i = lastMoveIndex + 1; i < moveCount; i++) {
              if (frame === moveFrames[i]) {
                  const progress = i / moveCount;
                  playPop(progress, audioCtx.currentTime);
                  lastMoveIndex = i;
              }
          }

          // Trigger Victory Audio
          if (frame === INTRO_FRAMES + FILL_FRAMES) {
              playVictory(audioCtx.currentTime);
          }

          frame++;
          // Use setTimeout for loop to allow non-blocking render, but target strict FPS
          setTimeout(render, 1000 / FPS);
      };

      render();
  });
}

