export interface ReplayMove {
  row: number;
  col: number;
  value: number;
  t?: number;
}

// Audio Synthesis Helper
function createReplayAudio(ctx: AudioContext, dest: MediaStreamAudioDestinationNode) {
    // 1. Standard Move Pop (Lower, accumulation feel)
    const playPop = (progress: number, t: number) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(dest);

        // Pitch scale: Exponential from C5 to C6 based on progress
        const freq = 523.25 * Math.pow(2, progress);
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, t);

        // Crisp, audible pop
        gain.gain.setValueAtTime(0, t);
        gain.gain.linearRampToValueAtTime(0.5, t + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);

        osc.start(t);
        osc.stop(t + 0.1);
    };

    // 2. Subtle Premium Victory (Soft Chord Swell)
    const playVictory = (t: number) => {
        const notes = [523.25, 659.25, 783.99, 987.77];

        notes.forEach((freq, i) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain);
            gain.connect(dest);

            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, t);

            const start = t + (i * 0.05); 

            gain.gain.setValueAtTime(0, start);
            gain.gain.linearRampToValueAtTime(0.15, start + 0.1); 
            gain.gain.exponentialRampToValueAtTime(0.001, start + 2.0); 

            osc.start(start);
            osc.stop(start + 2.5);
        });
    };

    return { playPop, playVictory };
}

export async function generateReplayVideo(
  initialBoard: Board,
  moves: ReplayMove[],
  difficulty: string,
  levelId: number,
  isDark: boolean,
  totalTime: number
): Promise<string | null> {
  if (typeof document === 'undefined') return null;

  const canvas = document.createElement('canvas');
  const size = 1080;
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  // Initialize Audio Context
  const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
  const audioCtx = new AudioContextClass();

  if (audioCtx.state === 'suspended') {
      try {
        await audioCtx.resume();
      } catch (e) {
        console.warn("Could not resume audio context", e);
      }
  }

  const dest = audioCtx.createMediaStreamDestination();
  const { playPop, playVictory } = createReplayAudio(audioCtx, dest);

  // --- CONFIGURATION ---
  const FPS = 30;
  const moveCount = moves.length;

  // Dynamic duration: Min 2s, Max 8s for moves.
  const MIN_FILL_MS = 2000;
  // If we have enough moves, we separate the last one.
  const movesForFill = moveCount > 1 ? moveCount - 1 : moveCount;
  const FILL_MS = Math.max(MIN_FILL_MS, Math.min(8000, movesForFill * 100)); 

  const INTRO_MS = 500; // 0.5s fade in
  // The "Final Chord" Delay: 600ms pause before the last move if we have a decent amount of moves
  const FINAL_PAUSE_MS = moveCount > 10 ? 600 : 0; 
  const OUTRO_MS = 2000; // 2s to show green board

  const INTRO_FRAMES = Math.floor((INTRO_MS / 1000) * FPS);
  const FILL_FRAMES = Math.floor((FILL_MS / 1000) * FPS);
  const PAUSE_FRAMES = Math.floor((FINAL_PAUSE_MS / 1000) * FPS);
  const OUTRO_FRAMES = Math.floor((OUTRO_MS / 1000) * FPS);

  const TOTAL_FRAMES = INTRO_FRAMES + FILL_FRAMES + PAUSE_FRAMES + OUTRO_FRAMES;
  const TOTAL_DURATION_MS = INTRO_MS + FILL_MS + FINAL_PAUSE_MS + OUTRO_MS;

  // Theme Colors
  const c = {
    bg: isDark ? '#1c1917' : '#fafaf9',
    boardBg: isDark ? '#292524' : '#ffffff',
    gridLineThin: isDark ? '#57534e' : '#e7e5e4',
    gridLineThick: isDark ? '#a8a29e' : '#78716c',
    textFixed: isDark ? '#f5f5f4' : '#292524',
    textInput: '#3b82f6',
    successBorder: '#10b981',
    watermark: isDark ? '#57534e' : '#a8a29e',
    target: isDark ? '#60a5fa' : '#3b82f6', // Focus color
  };

  const padding = 120;
  const boardSize = size - (padding * 2);
  const cellSize = boardSize / 9;
  const startX = padding;
  const startY = padding;

  const moveFrames = new Int32Array(moveCount);
  const BUFFER_FRAMES = 5; 

  if (moveCount > 0) {
      if (moveCount === 1) {
          moveFrames[0] = INTRO_FRAMES + FILL_FRAMES;
      } else {
          // Distribute moves 0 to N-2 across the FILL time
          const bulkCount = moveCount - 1;
          const availableBulkFrames = Math.max(1, FILL_FRAMES - BUFFER_FRAMES);

          for (let i = 0; i < bulkCount; i++) {
              // Linear distribution
              const progress = i / Math.max(1, bulkCount - 1);
              moveFrames[i] = INTRO_FRAMES + Math.floor(progress * availableBulkFrames);
          }

          // The Final Move gets the delayed slot (after FILL + PAUSE)
          moveFrames[moveCount - 1] = INTRO_FRAMES + FILL_FRAMES + PAUSE_FRAMES;
      }
  }

  // Calculate the exact frame the last move is placed to sync the timer
  const lastMoveFrame = moveCount > 0 ? moveFrames[moveCount - 1] : (INTRO_FRAMES + FILL_FRAMES);

  const formatTime = (seconds: number) => {
      const mins = Math.floor(seconds / 60);
      const secs = Math.floor(seconds % 60);
      return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // --- VISUAL RENDERER ---
  const drawBoard = (frame: number) => {
      // Background
      ctx.fillStyle = c.bg;
      ctx.fillRect(0, 0, size, size);

      // Intro Animation (Fade only, no scale)
      let globalOpacity = 1;
      if (frame < INTRO_FRAMES) {
          const t = frame / INTRO_FRAMES;
          globalOpacity = t * t * (3 - 2 * t); // Smoothstep
      }

      ctx.save();
      ctx.globalAlpha = globalOpacity;

      // 1. Header Info
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = c.textFixed;
      ctx.font = 'bold 40px "Outfit", sans-serif';
      const titleY = padding / 2;
      ctx.fillText(`${difficulty.toUpperCase()} • LEVEL ${levelId}`, size/2, titleY - 14);

      // 2. Timer (Interpolated)
      let currentSeconds = 0;
      if (frame < INTRO_FRAMES) {
          currentSeconds = 0;
      } else if (frame <= lastMoveFrame) {
          // Timer runs exactly from start of moves to the last move (slowing down during pause)
          const duration = Math.max(1, lastMoveFrame - INTRO_FRAMES);
          const progress = (frame - INTRO_FRAMES) / duration;
          currentSeconds = totalTime * progress;
      } else {
          currentSeconds = totalTime;
      }

      ctx.font = 'bold 40px "Outfit", sans-serif';
      ctx.fillText(formatTime(currentSeconds), size/2, titleY + 31);

      // 3. Watermark
      ctx.fillStyle = c.watermark;
      ctx.font = '500 30px "Outfit", sans-serif';
      ctx.fillText("OKU: SUDOKU", size/2, size - (padding / 2));

      // 4. Board Shadow & Base
      ctx.shadowColor = "rgba(0,0,0,0.1)";
      ctx.shadowBlur = 30;
      ctx.shadowOffsetY = 10;
      ctx.fillStyle = c.boardBg;
      const r = 32;
      ctx.beginPath();
      ctx.roundRect(startX, startY, boardSize, boardSize, r);
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.shadowOffsetY = 0;

      // 5. Grid Lines
      ctx.save();
      ctx.beginPath();
      ctx.roundRect(startX, startY, boardSize, boardSize, r);
      ctx.clip();

      ctx.lineCap = 'butt';
      for (let i = 1; i < 9; i++) {
          const pos = i * cellSize;
          const isThick = i % 3 === 0;
          ctx.lineWidth = isThick ? 6 : 2;
          ctx.strokeStyle = isThick ? c.gridLineThick : c.gridLineThin;

          // Vert
          ctx.beginPath();
          ctx.moveTo(startX + pos, startY);
          ctx.lineTo(startX + pos, startY + boardSize);
          ctx.stroke();

          // Horz
          ctx.beginPath();
          ctx.moveTo(startX, startY + pos);
          ctx.lineTo(startX + boardSize, startY + pos);
          ctx.stroke();
      }
      ctx.restore();

      // 6. Fixed Numbers
      ctx.font = `600 ${cellSize * 0.6}px "Outfit", sans-serif`;
      ctx.fillStyle = c.textFixed;

      initialBoard.forEach(row => {
          row.forEach(cell => {
              if (cell.isFixed && cell.value) {
                  const cx = startX + (cell.col * cellSize) + (cellSize / 2);
                  const cy = startY + (cell.row * cellSize) + (cellSize / 2);
                  ctx.fillText(cell.value.toString(), cx, cy + (cellSize * 0.05));
              }
          });
      });

      // 7. Moves (The Solve)
      if (frame >= INTRO_FRAMES) {
          ctx.font = `500 ${cellSize * 0.6}px "Outfit", sans-serif`;
          ctx.fillStyle = c.textInput;

          for (let i = 0; i < moveCount; i++) {
              const startFrame = moveFrames[i];

              if (frame >= startFrame) {
                  const move = moves[i];
                  const cx = startX + (move.col * cellSize) + (cellSize / 2);
                  const cy = startY + (move.row * cellSize) + (cellSize / 2);

                  // Pop animation
                  const age = frame - startFrame;
                  let numScale = 1;
                  if (age < 5) {
                      // Overshoot pop
                      numScale = 1.0 + (0.5 * (1 - (age / 5)));
                  }

                  ctx.save();
                  ctx.translate(cx, cy);
                  ctx.scale(numScale, numScale);
                  ctx.fillText(move.value.toString(), 0, (cellSize * 0.05));
                  ctx.restore();
              }
          }
      }

      // 8. The "Final Chord" Focus Animation (Targeting Reticle)
      // Only show if we have a pause and valid moves
      if (PAUSE_FRAMES > 0 && moveCount > 1) {
          const pauseStart = INTRO_FRAMES + FILL_FRAMES;
          const pauseEnd = moveFrames[moveCount - 1];

          if (frame >= pauseStart && frame < pauseEnd) {
             const lastMove = moves[moveCount - 1];
             const cx = startX + (lastMove.col * cellSize) + (cellSize / 2);
             const cy = startY + (lastMove.row * cellSize) + (cellSize / 2);

             // Animation progress 0 -> 1 during pause
             const p = (frame - pauseStart) / PAUSE_FRAMES;

             ctx.save();
             ctx.translate(cx, cy);

             // Gentle pulse/scale in
             // Scale goes from 1.3 to 1.0 roughly
             const scale = 1.3 - (0.3 * (1 - Math.pow(1 - p, 3))); 
             const alpha = Math.min(1, p * 3); // Fade in quickly

             ctx.strokeStyle = c.target;
             ctx.lineWidth = 4;
             ctx.globalAlpha = alpha * globalOpacity;
             ctx.scale(scale, scale);

             // Draw corner brackets
             const s = cellSize * 0.38; 
             const len = s * 0.35;

             ctx.beginPath();
             ctx.lineCap = 'round';
             // Top Left
             ctx.moveTo(-s, -s + len); ctx.lineTo(-s, -s); ctx.lineTo(-s + len, -s);
             // Top Right
             ctx.moveTo(s - len, -s); ctx.lineTo(s, -s); ctx.lineTo(s, -s + len);
             // Bottom Right
             ctx.moveTo(s, s - len); ctx.lineTo(s, s); ctx.lineTo(s - len, s);
             // Bottom Left
             ctx.moveTo(-s + len, s); ctx.lineTo(-s, s); ctx.lineTo(-s, s - len);

             ctx.stroke();
             ctx.restore();
          }
      }

      // 9. Victory Border Glow
      // Triggers after the last move is placed
      if (frame >= lastMoveFrame) {
          const outroAge = frame - lastMoveFrame;
          const alpha = Math.min(1, outroAge / 10);

          ctx.lineWidth = 12;
          ctx.strokeStyle = c.successBorder;
          ctx.globalAlpha = alpha * globalOpacity;

          ctx.beginPath();
          ctx.roundRect(startX - 2, startY - 2, boardSize + 4, boardSize + 4, r + 2);
          ctx.stroke();
      }

      ctx.restore();
  };

  // --- RECORDING SETUP ---
  // Initial draw
  drawBoard(0);

  const stream = canvas.captureStream(FPS);
  const audioTrack = dest.stream.getAudioTracks()[0];
  if (audioTrack) {
      stream.addTrack(audioTrack);
  }

  // Detect supported mime type
  let mimeType = 'video/webm';
  const possibleTypes = [
    'video/mp4; codecs=avc1', // Safari/iOS preference
    'video/mp4',
    'video/webm; codecs=vp9', // Chrome preference
    'video/webm'
  ];
  for (const t of possibleTypes) {
      if (MediaRecorder.isTypeSupported(t)) {
          mimeType = t;
          break;
      }
  }

  let mediaRecorder: MediaRecorder;
  try {
      // 3.0 Mbps for better quality
      mediaRecorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 3000000 });
  } catch (e) {
      console.error("MediaRecorder creation failed", e);
      audioCtx.close();
      return null;
  }

  const chunks: Blob[] = [];
  mediaRecorder.ondataavailable = (e) => {
    if (e.data.size > 0) chunks.push(e.data);
  };

  // Visibility Handler
  const handleVisibilityChange = () => {
      if (document.hidden && mediaRecorder.state === 'recording') {
          mediaRecorder.stop();
      }
  };
  document.addEventListener("visibilitychange", handleVisibilityChange);

  // Safety Timeout
  const safetyTimeout = setTimeout(() => {
      if (mediaRecorder.state === 'recording') {
          mediaRecorder.stop();
      }
  }, TOTAL_DURATION_MS + 2000); 

  const recordingPromise = new Promise<string | null>((resolve) => {
    mediaRecorder.onstop = () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      clearTimeout(safetyTimeout);
      try { audioCtx.close(); } catch(e) {}

      if (chunks.length === 0) {
           resolve(null);
           return;
      }
      const blob = new Blob(chunks, { type: mimeType });
      const url = URL.createObjectURL(blob);
      resolve(url);
    };
    mediaRecorder.onerror = (e) => {
        console.error("MediaRecorder error", e);
        try { audioCtx.close(); } catch(e2) {}
        resolve(null);
    };
  });

  // --- EXECUTION ---
  // 1. Start Recording Stream
  mediaRecorder.start();

  // 2. Pre-schedule Audio (Master Clock)
  const startTime = audioCtx.currentTime;

  // Schedule Move Pops
  for (let i = 0; i < moveCount; i++) {
      const timeOffset = moveFrames[i] / FPS; 
      playPop(i / Math.max(1, moveCount), startTime + timeOffset + 0.05);
  }

  // Schedule Victory Swell (After last move)
  const victoryTime = lastMoveFrame / FPS;
  playVictory(startTime + victoryTime + 0.05);

  // 3. Drive Visuals with Audio Clock
  const render = () => {
      const now = audioCtx.currentTime;
      const elapsed = now - startTime;

      const currentFrame = Math.floor(elapsed * FPS);

      if (currentFrame > TOTAL_FRAMES + 2) { 
          if (mediaRecorder.state === 'recording') mediaRecorder.stop();
          return;
      }

      drawBoard(currentFrame);
      requestAnimationFrame(render);
  };

  // Kickoff
  requestAnimationFrame(render);

  return recordingPromise;
}

import { Board } from '../types';

export interface ReplayMove {
  row: number;
  col: number;
  value: number;
  t?: number;
}

// Audio Synthesis Helper
function createReplayAudio(ctx: AudioContext, dest: MediaStreamAudioDestinationNode) {
    // 1. Standard Move Pop (Lower, accumulation feel)
    const playPop = (progress: number, t: number) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(dest);

        // Pitch scale: Exponential from C5 to C6 based on progress
        const freq = 523.25 * Math.pow(2, progress);
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, t);

        // Crisp, audible pop
        gain.gain.setValueAtTime(0, t);
        gain.gain.linearRampToValueAtTime(0.5, t + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);

        osc.start(t);
        osc.stop(t + 0.1);
    };

    // 2. Subtle Premium Victory (Soft Chord Swell)
    const playVictory = (t: number) => {
        const notes = [523.25, 659.25, 783.99, 987.77];

        notes.forEach((freq, i) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain);
            gain.connect(dest);

            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, t);

            const start = t + (i * 0.05); 

            gain.gain.setValueAtTime(0, start);
            gain.gain.linearRampToValueAtTime(0.15, start + 0.1); 
            gain.gain.exponentialRampToValueAtTime(0.001, start + 2.0); 

            osc.start(start);
            osc.stop(start + 2.5);
        });
    };

    return { playPop, playVictory };
}

export async function generateReplayVideo(
  initialBoard: Board,
  moves: ReplayMove[],
  difficulty: string,
  levelId: number,
  isDark: boolean,
  totalTime: number
): Promise<string | null> {
  if (typeof document === 'undefined') return null;

  const canvas = document.createElement('canvas');
  const size = 1080;
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  // Initialize Audio Context
  const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
  const audioCtx = new AudioContextClass();

  if (audioCtx.state === 'suspended') {
      try {
        await audioCtx.resume();
      } catch (e) {
        console.warn("Could not resume audio context", e);
      }
  }

  const dest = audioCtx.createMediaStreamDestination();
  const { playPop, playVictory } = createReplayAudio(audioCtx, dest);

  // --- CONFIGURATION ---
  const FPS = 30;
  const moveCount = moves.length;

  // Dynamic duration: Min 2s, Max 8s for moves.
  const MIN_FILL_MS = 2000;
  // If we have enough moves, we separate the last one.
  const movesForFill = moveCount > 1 ? moveCount - 1 : moveCount;
  const FILL_MS = Math.max(MIN_FILL_MS, Math.min(8000, movesForFill * 100)); 

  const INTRO_MS = 500; // 0.5s fade in
  // The "Final Chord" Delay: 600ms pause before the last move if we have a decent amount of moves
  const FINAL_PAUSE_MS = moveCount > 10 ? 600 : 0; 
  const OUTRO_MS = 2000; // 2s to show green board

  const INTRO_FRAMES = Math.floor((INTRO_MS / 1000) * FPS);
  const FILL_FRAMES = Math.floor((FILL_MS / 1000) * FPS);
  const PAUSE_FRAMES = Math.floor((FINAL_PAUSE_MS / 1000) * FPS);
  const OUTRO_FRAMES = Math.floor((OUTRO_MS / 1000) * FPS);

  const TOTAL_FRAMES = INTRO_FRAMES + FILL_FRAMES + PAUSE_FRAMES + OUTRO_FRAMES;
  const TOTAL_DURATION_MS = INTRO_MS + FILL_MS + FINAL_PAUSE_MS + OUTRO_MS;

  // Theme Colors
  const c = {
    bg: isDark ? '#1c1917' : '#fafaf9',
    boardBg: isDark ? '#292524' : '#ffffff',
    gridLineThin: isDark ? '#57534e' : '#e7e5e4',
    gridLineThick: isDark ? '#a8a29e' : '#78716c',
    textFixed: isDark ? '#f5f5f4' : '#292524',
    textInput: '#3b82f6',
    successBorder: '#10b981',
    watermark: isDark ? '#57534e' : '#a8a29e',
    target: isDark ? '#60a5fa' : '#3b82f6', // Focus color
  };

  const padding = 120;
  const boardSize = size - (padding * 2);
  const cellSize = boardSize / 9;
  const startX = padding;
  const startY = padding;

  const moveFrames = new Int32Array(moveCount);
  const BUFFER_FRAMES = 5; 

  if (moveCount > 0) {
      if (moveCount === 1) {
          moveFrames[0] = INTRO_FRAMES + FILL_FRAMES;
      } else {
          // Distribute moves 0 to N-2 across the FILL time
          const bulkCount = moveCount - 1;
          const availableBulkFrames = Math.max(1, FILL_FRAMES - BUFFER_FRAMES);

          for (let i = 0; i < bulkCount; i++) {
              // Linear distribution
              const progress = i / Math.max(1, bulkCount - 1);
              moveFrames[i] = INTRO_FRAMES + Math.floor(progress * availableBulkFrames);
          }

          // The Final Move gets the delayed slot (after FILL + PAUSE)
          moveFrames[moveCount - 1] = INTRO_FRAMES + FILL_FRAMES + PAUSE_FRAMES;
      }
  }

  // Calculate the exact frame the last move is placed to sync the timer
  const lastMoveFrame = moveCount > 0 ? moveFrames[moveCount - 1] : (INTRO_FRAMES + FILL_FRAMES);

  const formatTime = (seconds: number) => {
      const mins = Math.floor(seconds / 60);
      const secs = Math.floor(seconds % 60);
      return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // --- VISUAL RENDERER ---
  const drawBoard = (frame: number) => {
      // Background
      ctx.fillStyle = c.bg;
      ctx.fillRect(0, 0, size, size);

      // Intro Animation (Fade only, no scale)
      let globalOpacity = 1;
      if (frame < INTRO_FRAMES) {
          const t = frame / INTRO_FRAMES;
          globalOpacity = t * t * (3 - 2 * t); // Smoothstep
      }

      ctx.save();
      ctx.globalAlpha = globalOpacity;

      // 1. Header Info
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = c.textFixed;
      ctx.font = 'bold 40px "Outfit", sans-serif';
      const titleY = padding / 2;
      ctx.fillText(`${difficulty.toUpperCase()} • LEVEL ${levelId}`, size/2, titleY - 14);

      // 2. Timer (Interpolated)
      let currentSeconds = 0;
      if (frame < INTRO_FRAMES) {
          currentSeconds = 0;
      } else if (frame <= lastMoveFrame) {
          // Timer runs exactly from start of moves to the last move (slowing down during pause)
          const duration = Math.max(1, lastMoveFrame - INTRO_FRAMES);
          const progress = (frame - INTRO_FRAMES) / duration;
          currentSeconds = totalTime * progress;
      } else {
          currentSeconds = totalTime;
      }

      ctx.font = 'bold 40px "Outfit", sans-serif';
      ctx.fillText(formatTime(currentSeconds), size/2, titleY + 31);

      // 3. Watermark
      ctx.fillStyle = c.watermark;
      ctx.font = '500 30px "Outfit", sans-serif';
      ctx.fillText("OKU: SUDOKU", size/2, size - (padding / 2));

      // 4. Board Shadow & Base
      ctx.shadowColor = "rgba(0,0,0,0.1)";
      ctx.shadowBlur = 30;
      ctx.shadowOffsetY = 10;
      ctx.fillStyle = c.boardBg;
      const r = 32;
      ctx.beginPath();
      ctx.roundRect(startX, startY, boardSize, boardSize, r);
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.shadowOffsetY = 0;

      // 5. Grid Lines
      ctx.save();
      ctx.beginPath();
      ctx.roundRect(startX, startY, boardSize, boardSize, r);
      ctx.clip();

      ctx.lineCap = 'butt';
      for (let i = 1; i < 9; i++) {
          const pos = i * cellSize;
          const isThick = i % 3 === 0;
          ctx.lineWidth = isThick ? 6 : 2;
          ctx.strokeStyle = isThick ? c.gridLineThick : c.gridLineThin;

          // Vert
          ctx.beginPath();
          ctx.moveTo(startX + pos, startY);
          ctx.lineTo(startX + pos, startY + boardSize);
          ctx.stroke();

          // Horz
          ctx.beginPath();
          ctx.moveTo(startX, startY + pos);
          ctx.lineTo(startX + boardSize, startY + pos);
          ctx.stroke();
      }
      ctx.restore();

      // 6. Fixed Numbers
      ctx.font = `600 ${cellSize * 0.6}px "Outfit", sans-serif`;
      ctx.fillStyle = c.textFixed;

      initialBoard.forEach(row => {
          row.forEach(cell => {
              if (cell.isFixed && cell.value) {
                  const cx = startX + (cell.col * cellSize) + (cellSize / 2);
                  const cy = startY + (cell.row * cellSize) + (cellSize / 2);
                  ctx.fillText(cell.value.toString(), cx, cy + (cellSize * 0.05));
              }
          });
      });

      // 7. Moves (The Solve)
      if (frame >= INTRO_FRAMES) {
          ctx.font = `500 ${cellSize * 0.6}px "Outfit", sans-serif`;
          ctx.fillStyle = c.textInput;

          for (let i = 0; i < moveCount; i++) {
              const startFrame = moveFrames[i];

              if (frame >= startFrame) {
                  const move = moves[i];
                  const cx = startX + (move.col * cellSize) + (cellSize / 2);
                  const cy = startY + (move.row * cellSize) + (cellSize / 2);
                  const age = frame - startFrame;

                  // 7b. Particle Bursts (Juice)
                  if (age < 15) {
                      const pCount = 5;
                      const isLast = i === moveCount - 1;
                      const pColor = isLast ? c.successBorder : c.textInput;

                      ctx.save();
                      for (let k = 0; k < pCount; k++) {
                          const seed = (i * 17) + (k * 31);
                          const rAngle = Math.abs(Math.sin(seed));
                          const rSpeed = Math.abs(Math.cos(seed * 123));

                          const angle = rAngle * Math.PI * 2;
                          // Speed: approx 0.1 to 0.25 cell size per frame
                          const speed = (cellSize * 0.1) + (rSpeed * cellSize * 0.15); 

                          const px = cx + Math.cos(angle) * speed * age;
                          const py = cy + Math.sin(angle) * speed * age;

                          const lifePct = 1 - (age / 15);
                          const size = (cellSize * 0.14) * lifePct; // Start slightly smaller than text

                          ctx.globalAlpha = lifePct * globalOpacity;
                          ctx.fillStyle = pColor;

                          ctx.beginPath();
                          // Small squares for grid aesthetic
                          ctx.fillRect(px - size/2, py - size/2, size, size);
                      }
                      ctx.restore();
                  }

                  // Pop animation for number
                  let numScale = 1;
                  if (age < 5) {
                      // Overshoot pop
                      numScale = 1.0 + (0.5 * (1 - (age / 5)));
                  }

                  ctx.save();
                  ctx.translate(cx, cy);
                  ctx.scale(numScale, numScale);
                  ctx.fillText(move.value.toString(), 0, (cellSize * 0.05));
                  ctx.restore();
              }
          }
      }

      // 8. The "Final Chord" Focus Animation (Targeting Reticle)
      // Only show if we have a pause and valid moves
      if (PAUSE_FRAMES > 0 && moveCount > 1) {
          const pauseStart = INTRO_FRAMES + FILL_FRAMES;
          const pauseEnd = moveFrames[moveCount - 1];

          if (frame >= pauseStart && frame < pauseEnd) {
             const lastMove = moves[moveCount - 1];
             const cx = startX + (lastMove.col * cellSize) + (cellSize / 2);
             const cy = startY + (lastMove.row * cellSize) + (cellSize / 2);

             // Animation progress 0 -> 1 during pause
             const p = (frame - pauseStart) / PAUSE_FRAMES;

             ctx.save();
             ctx.translate(cx, cy);

             // Gentle pulse/scale in
             // Scale goes from 1.3 to 1.0 roughly
             const scale = 1.3 - (0.3 * (1 - Math.pow(1 - p, 3))); 
             const alpha = Math.min(1, p * 3); // Fade in quickly

             ctx.strokeStyle = c.target;
             ctx.lineWidth = 4;
             ctx.globalAlpha = alpha * globalOpacity;
             ctx.scale(scale, scale);

             // Draw corner brackets
             const s = cellSize * 0.38; 
             const len = s * 0.35;

             ctx.beginPath();
             ctx.lineCap = 'round';
             // Top Left
             ctx.moveTo(-s, -s + len); ctx.lineTo(-s, -s); ctx.lineTo(-s + len, -s);
             // Top Right
             ctx.moveTo(s - len, -s); ctx.lineTo(s, -s); ctx.lineTo(s, -s + len);
             // Bottom Right
             ctx.moveTo(s, s - len); ctx.lineTo(s, s); ctx.lineTo(s - len, s);
             // Bottom Left
             ctx.moveTo(-s + len, s); ctx.lineTo(-s, s); ctx.lineTo(-s, s - len);

             ctx.stroke();
             ctx.restore();
          }
      }

      // 9. Victory Border Glow
      // Triggers after the last move is placed
      if (frame >= lastMoveFrame) {
          const outroAge = frame - lastMoveFrame;
          const alpha = Math.min(1, outroAge / 10);

          ctx.lineWidth = 12;
          ctx.strokeStyle = c.successBorder;
          ctx.globalAlpha = alpha * globalOpacity;

          ctx.beginPath();
          ctx.roundRect(startX - 2, startY - 2, boardSize + 4, boardSize + 4, r + 2);
          ctx.stroke();
      }

      ctx.restore();
  };

  // --- RECORDING SETUP ---
  // Initial draw
  drawBoard(0);

  const stream = canvas.captureStream(FPS);
  const audioTrack = dest.stream.getAudioTracks()[0];
  if (audioTrack) {
      stream.addTrack(audioTrack);
  }

  // Detect supported mime type
  let mimeType = 'video/webm';
  const possibleTypes = [
    'video/mp4; codecs=avc1', // Safari/iOS preference
    'video/mp4',
    'video/webm; codecs=vp9', // Chrome preference
    'video/webm'
  ];
  for (const t of possibleTypes) {
      if (MediaRecorder.isTypeSupported(t)) {
          mimeType = t;
          break;
      }
  }

  let mediaRecorder: MediaRecorder;
  try {
      // 3.0 Mbps for better quality
      mediaRecorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 3000000 });
  } catch (e) {
      console.error("MediaRecorder creation failed", e);
      audioCtx.close();
      return null;
  }

  const chunks: Blob[] = [];
  mediaRecorder.ondataavailable = (e) => {
    if (e.data.size > 0) chunks.push(e.data);
  };

  // Visibility Handler
  const handleVisibilityChange = () => {
      if (document.hidden && mediaRecorder.state === 'recording') {
          mediaRecorder.stop();
      }
  };
  document.addEventListener("visibilitychange", handleVisibilityChange);

  // Safety Timeout
  const safetyTimeout = setTimeout(() => {
      if (mediaRecorder.state === 'recording') {
          mediaRecorder.stop();
      }
  }, TOTAL_DURATION_MS + 2000); 

  const recordingPromise = new Promise<string | null>((resolve) => {
    mediaRecorder.onstop = () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      clearTimeout(safetyTimeout);
      try { audioCtx.close(); } catch(e) {}

      if (chunks.length === 0) {
           resolve(null);
           return;
      }
      const blob = new Blob(chunks, { type: mimeType });
      const url = URL.createObjectURL(blob);
      resolve(url);
    };
    mediaRecorder.onerror = (e) => {
        console.error("MediaRecorder error", e);
        try { audioCtx.close(); } catch(e2) {}
        resolve(null);
    };
  });

  // --- EXECUTION ---
  // 1. Start Recording Stream
  mediaRecorder.start();

  // 2. Pre-schedule Audio (Master Clock)
  const startTime = audioCtx.currentTime;

  // Schedule Move Pops
  for (let i = 0; i < moveCount; i++) {
      const timeOffset = moveFrames[i] / FPS; 
      playPop(i / Math.max(1, moveCount), startTime + timeOffset + 0.05);
  }

  // Schedule Victory Swell (After last move)
  const victoryTime = lastMoveFrame / FPS;
  playVictory(startTime + victoryTime + 0.05);

  // 3. Drive Visuals with Audio Clock
  const render = () => {
      const now = audioCtx.currentTime;
      const elapsed = now - startTime;

      const currentFrame = Math.floor(elapsed * FPS);

      if (currentFrame > TOTAL_FRAMES + 2) { 
          if (mediaRecorder.state === 'recording') mediaRecorder.stop();
          return;
      }

      drawBoard(currentFrame);
      requestAnimationFrame(render);
  };

  // Kickoff
  requestAnimationFrame(render);

  return recordingPromise;
}

import { Board } from '../types';

export interface ReplayMove {
  row: number;
  col: number;
  value: number;
  t?: number;
}

// Audio Synthesis Helper
function createReplayAudio(ctx: AudioContext, dest: MediaStreamAudioDestinationNode) {
    // 1. Standard Move Pop (Lower, accumulation feel)
    const playPop = (progress: number, t: number) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(dest);

        // Pitch scale: Exponential from C5 to C6 based on progress
        const freq = 523.25 * Math.pow(2, progress);
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, t);

        // Crisp, audible pop
        gain.gain.setValueAtTime(0, t);
        gain.gain.linearRampToValueAtTime(0.5, t + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);

        osc.start(t);
        osc.stop(t + 0.1);
    };

    // 2. Subtle Premium Victory (Soft Chord Swell)
    const playVictory = (t: number) => {
        const notes = [523.25, 659.25, 783.99, 987.77];

        notes.forEach((freq, i) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain);
            gain.connect(dest);

            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, t);

            const start = t + (i * 0.05); 

            gain.gain.setValueAtTime(0, start);
            gain.gain.linearRampToValueAtTime(0.15, start + 0.1); 
            gain.gain.exponentialRampToValueAtTime(0.001, start + 2.0); 

            osc.start(start);
            osc.stop(start + 2.5);
        });
    };

    return { playPop, playVictory };
}

export async function generateReplayVideo(
  initialBoard: Board,
  moves: ReplayMove[],
  difficulty: string,
  levelId: number,
  isDark: boolean,
  totalTime: number
): Promise<string | null> {
  if (typeof document === 'undefined') return null;

  const canvas = document.createElement('canvas');
  const size = 1080;
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  // Initialize Audio Context
  const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
  const audioCtx = new AudioContextClass();

  if (audioCtx.state === 'suspended') {
      try {
        await audioCtx.resume();
      } catch (e) {
        console.warn("Could not resume audio context", e);
      }
  }

  const dest = audioCtx.createMediaStreamDestination();
  const { playPop, playVictory } = createReplayAudio(audioCtx, dest);

  // --- CONFIGURATION ---
  const FPS = 30;
  const moveCount = moves.length;

  // Dynamic duration: Min 2s, Max 8s for moves.
  const MIN_FILL_MS = 2000;
  // If we have enough moves, we separate the last one.
  const movesForFill = moveCount > 1 ? moveCount - 1 : moveCount;
  const FILL_MS = Math.max(MIN_FILL_MS, Math.min(8000, movesForFill * 100)); 

  const INTRO_MS = 500; // 0.5s fade in
  // The "Final Chord" Delay: 600ms pause before the last move if we have a decent amount of moves
  const FINAL_PAUSE_MS = moveCount > 10 ? 600 : 0; 
  const OUTRO_MS = 2000; // 2s to show green board

  const INTRO_FRAMES = Math.floor((INTRO_MS / 1000) * FPS);
  const FILL_FRAMES = Math.floor((FILL_MS / 1000) * FPS);
  const PAUSE_FRAMES = Math.floor((FINAL_PAUSE_MS / 1000) * FPS);
  const OUTRO_FRAMES = Math.floor((OUTRO_MS / 1000) * FPS);

  const TOTAL_FRAMES = INTRO_FRAMES + FILL_FRAMES + PAUSE_FRAMES + OUTRO_FRAMES;
  const TOTAL_DURATION_MS = INTRO_MS + FILL_MS + FINAL_PAUSE_MS + OUTRO_MS;

  // Theme Colors
  const c = {
    bg: isDark ? '#1c1917' : '#fafaf9',
    boardBg: isDark ? '#292524' : '#ffffff',
    gridLineThin: isDark ? '#57534e' : '#e7e5e4',
    gridLineThick: isDark ? '#a8a29e' : '#78716c',
    textFixed: isDark ? '#f5f5f4' : '#292524',
    textInput: '#3b82f6',
    successBorder: '#10b981',
    watermark: isDark ? '#57534e' : '#a8a29e',
    target: isDark ? '#60a5fa' : '#3b82f6', // Focus color
  };

  const padding = 120;
  const boardSize = size - (padding * 2);
  const cellSize = boardSize / 9;
  const startX = padding;
  const startY = padding;

  const moveFrames = new Int32Array(moveCount);
  const BUFFER_FRAMES = 5; 

  if (moveCount > 0) {
      if (moveCount === 1) {
          moveFrames[0] = INTRO_FRAMES + FILL_FRAMES;
      } else {
          // Distribute moves 0 to N-2 across the FILL time
          const bulkCount = moveCount - 1;
          const availableBulkFrames = Math.max(1, FILL_FRAMES - BUFFER_FRAMES);

          for (let i = 0; i < bulkCount; i++) {
              // Linear distribution
              const progress = i / Math.max(1, bulkCount - 1);
              moveFrames[i] = INTRO_FRAMES + Math.floor(progress * availableBulkFrames);
          }

          // The Final Move gets the delayed slot (after FILL + PAUSE)
          moveFrames[moveCount - 1] = INTRO_FRAMES + FILL_FRAMES + PAUSE_FRAMES;
      }
  }

  // Calculate the exact frame the last move is placed to sync the timer
  const lastMoveFrame = moveCount > 0 ? moveFrames[moveCount - 1] : (INTRO_FRAMES + FILL_FRAMES);

  const formatTime = (seconds: number) => {
      const mins = Math.floor(seconds / 60);
      const secs = Math.floor(seconds % 60);
      return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // --- VISUAL RENDERER ---
  const drawBoard = (frame: number) => {
      // Background
      ctx.fillStyle = c.bg;
      ctx.fillRect(0, 0, size, size);

      // Intro Animation (Fade only, no scale)
      let globalOpacity = 1;
      if (frame < INTRO_FRAMES) {
          const t = frame / INTRO_FRAMES;
          globalOpacity = t * t * (3 - 2 * t); // Smoothstep
      }

      ctx.save();
      ctx.globalAlpha = globalOpacity;

      // 1. Header Info
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = c.textFixed;
      ctx.font = 'bold 40px "Outfit", sans-serif';
      const titleY = padding / 2;
      ctx.fillText(`${difficulty.toUpperCase()} • LEVEL ${levelId}`, size/2, titleY - 14);

      // 2. Timer (Interpolated)
      let currentSeconds = 0;
      if (frame < INTRO_FRAMES) {
          currentSeconds = 0;
      } else if (frame <= lastMoveFrame) {
          // Timer runs exactly from start of moves to the last move (slowing down during pause)
          const duration = Math.max(1, lastMoveFrame - INTRO_FRAMES);
          const progress = (frame - INTRO_FRAMES) / duration;
          currentSeconds = totalTime * progress;
      } else {
          currentSeconds = totalTime;
      }

      ctx.font = 'bold 40px "Outfit", sans-serif';
      ctx.fillText(formatTime(currentSeconds), size/2, titleY + 31);

      // 3. Watermark
      ctx.fillStyle = c.watermark;
      ctx.font = '500 30px "Outfit", sans-serif';
      ctx.fillText("OKU: SUDOKU", size/2, size - (padding / 2));

      // 4. Board Shadow & Base
      ctx.shadowColor = "rgba(0,0,0,0.1)";
      ctx.shadowBlur = 30;
      ctx.shadowOffsetY = 10;
      ctx.fillStyle = c.boardBg;
      const r = 32;
      ctx.beginPath();
      ctx.roundRect(startX, startY, boardSize, boardSize, r);
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.shadowOffsetY = 0;

      // 5. Grid Lines
      ctx.save();
      ctx.beginPath();
      ctx.roundRect(startX, startY, boardSize, boardSize, r);
      ctx.clip();

      ctx.lineCap = 'butt';
      for (let i = 1; i < 9; i++) {
          const pos = i * cellSize;
          const isThick = i % 3 === 0;
          ctx.lineWidth = isThick ? 6 : 2;
          ctx.strokeStyle = isThick ? c.gridLineThick : c.gridLineThin;

          // Vert
          ctx.beginPath();
          ctx.moveTo(startX + pos, startY);
          ctx.lineTo(startX + pos, startY + boardSize);
          ctx.stroke();

          // Horz
          ctx.beginPath();
          ctx.moveTo(startX, startY + pos);
          ctx.lineTo(startX + boardSize, startY + pos);
          ctx.stroke();
      }
      ctx.restore();

      // 6. Fixed Numbers
      ctx.font = `600 ${cellSize * 0.6}px "Outfit", sans-serif`;
      ctx.fillStyle = c.textFixed;

      initialBoard.forEach(row => {
          row.forEach(cell => {
              if (cell.isFixed && cell.value) {
                  const cx = startX + (cell.col * cellSize) + (cellSize / 2);
                  const cy = startY + (cell.row * cellSize) + (cellSize / 2);
                  ctx.fillText(cell.value.toString(), cx, cy + (cellSize * 0.05));
              }
          });
      });

      // 7. Moves (The Solve)
      if (frame >= INTRO_FRAMES) {
          ctx.font = `500 ${cellSize * 0.6}px "Outfit", sans-serif`;
          ctx.fillStyle = c.textInput;

          for (let i = 0; i < moveCount; i++) {
              const startFrame = moveFrames[i];

              if (frame >= startFrame) {
                  const move = moves[i];
                  const cx = startX + (move.col * cellSize) + (cellSize / 2);
                  const cy = startY + (move.row * cellSize) + (cellSize / 2);
                  const age = frame - startFrame;

                  // Pop animation for number
                  let numScale = 1;
                  if (age < 5) {
                      // Overshoot pop
                      numScale = 1.0 + (0.5 * (1 - (age / 5)));
                  }

                  ctx.save();
                  ctx.translate(cx, cy);
                  ctx.scale(numScale, numScale);
                  ctx.fillText(move.value.toString(), 0, (cellSize * 0.05));
                  ctx.restore();
              }
          }
      }

      // 8. Victory Border Glow
      // Triggers after the last move is placed
      if (frame >= lastMoveFrame) {
          const outroAge = frame - lastMoveFrame;
          const alpha = Math.min(1, outroAge / 10);

          ctx.lineWidth = 12;
          ctx.strokeStyle = c.successBorder;
          ctx.globalAlpha = alpha * globalOpacity;

          ctx.beginPath();
          ctx.roundRect(startX - 2, startY - 2, boardSize + 4, boardSize + 4, r + 2);
          ctx.stroke();
      }

      ctx.restore();
  };

  // --- RECORDING SETUP ---
  // Initial draw
  drawBoard(0);

  const stream = canvas.captureStream(FPS);
  const audioTrack = dest.stream.getAudioTracks()[0];
  if (audioTrack) {
      stream.addTrack(audioTrack);
  }

  // Detect supported mime type
  let mimeType = 'video/webm';
  const possibleTypes = [
    'video/mp4; codecs=avc1', // Safari/iOS preference
    'video/mp4',
    'video/webm; codecs=vp9', // Chrome preference
    'video/webm'
  ];
  for (const t of possibleTypes) {
      if (MediaRecorder.isTypeSupported(t)) {
          mimeType = t;
          break;
      }
  }

  let mediaRecorder: MediaRecorder;
  try {
      // 3.0 Mbps for better quality
      mediaRecorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 3000000 });
  } catch (e) {
      console.error("MediaRecorder creation failed", e);
      audioCtx.close();
      return null;
  }

  const chunks: Blob[] = [];
  mediaRecorder.ondataavailable = (e) => {
    if (e.data.size > 0) chunks.push(e.data);
  };

  // Visibility Handler
  const handleVisibilityChange = () => {
      if (document.hidden && mediaRecorder.state === 'recording') {
          mediaRecorder.stop();
      }
  };
  document.addEventListener("visibilitychange", handleVisibilityChange);

  // Safety Timeout
  const safetyTimeout = setTimeout(() => {
      if (mediaRecorder.state === 'recording') {
          mediaRecorder.stop();
      }
  }, TOTAL_DURATION_MS + 2000); 

  const recordingPromise = new Promise<string | null>((resolve) => {
    mediaRecorder.onstop = () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      clearTimeout(safetyTimeout);
      try { audioCtx.close(); } catch(e) {}

      if (chunks.length === 0) {
           resolve(null);
           return;
      }
      const blob = new Blob(chunks, { type: mimeType });
      const url = URL.createObjectURL(blob);
      resolve(url);
    };
    mediaRecorder.onerror = (e) => {
        console.error("MediaRecorder error", e);
        try { audioCtx.close(); } catch(e2) {}
        resolve(null);
    };
  });

  // --- EXECUTION ---
  // 1. Start Recording Stream
  mediaRecorder.start();

  // 2. Pre-schedule Audio (Master Clock)
  const startTime = audioCtx.currentTime;

  // Schedule Move Pops
  for (let i = 0; i < moveCount; i++) {
      const timeOffset = moveFrames[i] / FPS; 
      playPop(i / Math.max(1, moveCount), startTime + timeOffset + 0.05);
  }

  // Schedule Victory Swell (After last move)
  const victoryTime = lastMoveFrame / FPS;
  playVictory(startTime + victoryTime + 0.05);

  // 3. Drive Visuals with Audio Clock
  const render = () => {
      const now = audioCtx.currentTime;
      const elapsed = now - startTime;

      const currentFrame = Math.floor(elapsed * FPS);

      if (currentFrame > TOTAL_FRAMES + 2) { 
          if (mediaRecorder.state === 'recording') mediaRecorder.stop();
          return;
      }

      drawBoard(currentFrame);
      requestAnimationFrame(render);
  };

  // Kickoff
  requestAnimationFrame(render);

  return recordingPromise;
}
